TODAY = '2026-11-12'

NORM = {'debattu': 'debat', 'probable': 'interpretation'}  # valeurs de fiabilité reconnues par l'application

def fiche(**k):
    d = _fiche(**k)
    d['fiabilite'] = NORM.get(d['fiabilite'], d['fiabilite'])
    for f in d.get('faits', []):
        f['fiabilite'] = NORM.get(f.get('fiabilite'), f.get('fiabilite'))
    d['derniere_verification'] = TODAY
    return d

