FICHES.append(fiche(
 id='lfi-allocation-autonomie-jeunes', affirmation="LFI veut payer les jeunes à ne rien faire avec une allocation d'autonomie.", volet='politique', sous_theme='Programmes électoraux',
 mots_cles=['lfi allocation autonomie jeunes', 'garantie autonomie jeunes', 'melenchon payer les jeunes', 'rsa jeunes lfi', 'revenu jeunes insoumis', 'allocation jeunes a ne rien faire', 'avenir en commun jeunes', 'nfp garantie autonomie', 'jeunes assistes lfi', 'revenu etudiant melenchon'],
 verdict='trompeur', fiabilite='etabli',
 resume="Trompeur. LFI propose une « garantie d'autonomie » pour que les jeunes détachés du foyer fiscal de leurs parents ne vivent pas sous le seuil de pauvreté (1 337 € selon le programme). C'est un complément de revenu, pas un salaire versé à tous. En 2022, elle était réservée aux jeunes en formation qualifiante, sous conditions de ressources. Elle vise un vrai problème : 18,6 % des 18-29 ans sont pauvres en 2024, alors que le RSA est presque fermé aux moins de 25 ans.",
 contexte="La France insoumise défend depuis 2017 une garantie ou allocation d'autonomie pour les jeunes ; le Nouveau Front populaire l'a reprise en 2024. Ses adversaires la présentent comme une prime à l'oisiveté.",
 explication="Il faut lire ce que dit exactement le programme (montant, public, conditions), le comparer aux aides existantes pour les jeunes et à leur taux de pauvreté.",
 sources=[PA_AEC_2027_JEUNES, PA_MONTAIGNE_GARANTIE_2022, PA_CIDJ_NFP_2024, PA_INSEE_PAUVRETE_AGE_2026, PA_LFPT_RSA_JEUNES, PA_AN_PPL_2586_2026],
 faits=[
  fait("Le programme L'Avenir en commun (version 2026) propose de « Financer l'autonomie des jeunes détachés du foyer fiscal parental » par une garantie qui les porte au-dessus du seuil de pauvreté, chiffré à 1 337 € pour une personne seule.", 'pa_aec_2027_jeunes', '2026', 'France', "C'est un plancher de revenu, calculé pour sortir de la pauvreté.", 'etabli', '1 337 €'),
  fait("En 2022, la garantie était un complément de revenu jusqu'à 1 063 € par mois pendant trois ans, sous conditions de ressources et sous réserve d'une formation qualifiante ; les jeunes rattachés au foyer fiscal de leurs parents en étaient exclus.", 'pa_montaigne_garantie_2022', '2022', 'France', "La version chiffrée exigeait d'être en formation : l'inverse de « ne rien faire ».", 'etabli', '1 063 €'),
  fait("En 2024, le programme du Nouveau Front populaire visait une garantie qui « complète les revenus des ménages situés sous le seuil de pauvreté », dès 18 ans pour les jeunes indépendants fiscalement et dès 16 ans pour les élèves de l'enseignement professionnel.", 'pa_cidj_nfp_2024', '2024', 'France', "La mesure est ciblée sur les jeunes pauvres.", 'etabli'),
  fait("En 2024, 18,6 % des 18-29 ans vivent sous le seuil de pauvreté à 60 %, contre 15,4 % de l'ensemble de la population.", 'pa_insee_pauvrete_age_2026', '2024', 'France', "Les jeunes adultes sont plus touchés par la pauvreté que la moyenne.", 'etabli', '18,6 %'),
  fait("Avant 25 ans, le RSA suppose d'avoir travaillé au moins deux ans à temps plein sur les trois dernières années ; les étudiants n'y ont pas droit, sauf s'ils sont parents isolés.", 'pa_lfpt_rsa_jeunes', '2025', 'France', "La plupart des jeunes pauvres n'ont aujourd'hui aucun minimum social.", 'etabli'),
  fait("Fait défavorable : la version 2026 du programme lue ne mentionne plus de condition de formation, seulement le fait d'être détaché du foyer fiscal parental ; et la mesure coûterait cher, 10,3 Md€ par an selon LFI en 2022, plus de 12 Md€ selon l'Institut Montaigne.", 'pa_montaigne_garantie_2022', '2022-2026', 'France', "Le coût et les contreparties sont de vrais sujets de débat, à discuter sur pièces.", 'estimation', '10,3 Md€'),
 ],
 court="Ce n'est pas un salaire pour ne rien faire : c'est un complément de revenu pour que les jeunes indépendants ne vivent pas sous le seuil de pauvreté. En 2022, il fallait être en formation. Aujourd'hui, 18,6 % des 18-29 ans sont pauvres, et le RSA est presque fermé aux moins de 25 ans.",
 moyen="LFI propose une « garantie d'autonomie » pour les jeunes détachés du foyer fiscal de leurs parents, qui les porterait au-dessus du seuil de pauvreté (1 337 € selon le programme). C'est un complément : un jeune qui gagne déjà un peu touche la différence. En 2022, il fallait être en formation qualifiante et sous conditions de ressources.\n\nLe besoin est réel : 18,6 % des 18-29 ans vivent sous le seuil de pauvreté en 2024. Avant 25 ans, le RSA exige d'avoir travaillé deux ans à temps plein, et les étudiants en sont exclus. On peut débattre du coût, plus de 10 milliards par an, mais pas présenter la mesure comme une prime à la paresse.",
 detaille="Le programme L'Avenir en commun propose de « financer l'autonomie des jeunes détachés du foyer fiscal parental » par une garantie qui les porte au-dessus du seuil de pauvreté, chiffré à 1 337 € pour une personne seule. Il s'agit d'un complément : seul l'écart entre les revenus du jeune et ce seuil serait versé. En 2022, la version chiffrée prévoyait jusqu'à 1 063 € par mois pendant trois ans, sous conditions de ressources et à condition de suivre une formation qualifiante. Le Nouveau Front populaire l'a reprise en 2024 pour les jeunes indépendants fiscalement et les élèves de lycée professionnel.\n\nLa mesure répond à un trou dans la protection sociale. En 2024, 18,6 % des 18-29 ans vivent sous le seuil de pauvreté, contre 15,4 % de la population. Pourtant, avant 25 ans, le RSA suppose d'avoir travaillé au moins deux ans à temps plein sur trois ans, et les étudiants en sont exclus. Le même programme prévoit aussi des emplois pour les jeunes, des logements, des stages mieux payés et un service citoyen : il ne s'agit pas de payer l'inactivité.\n\nLa critique la plus sérieuse porte sur le coût : 10,3 milliards d'euros par an selon LFI en 2022, plus de 12 milliards selon l'Institut Montaigne. Et la version actuelle du programme ne précise plus de condition de formation. Ces points méritent un débat. Mais l'idée de fond est simple : à 20 ans, on devrait pouvoir étudier ou chercher sa voie sans dépendre entièrement de ses parents, ni basculer dans la misère.",
 empathie="Quand on a travaillé dur dès sa jeunesse, l'idée d'aider des jeunes sans contrepartie peut choquer. Ce sentiment de justice est respectable ; regardons ce que propose vraiment le texte.",
 legitimes=["La mesure coûterait plus de 10 milliards d'euros par an selon les estimations disponibles.", "La version actuelle du programme lue ne détaille ni les conditions de formation ni l'âge exact."],
 contre=[
  ("Ils n'auront plus envie de travailler.", "C'est un complément jusqu'au seuil de pauvreté, pas un revenu en plus : travailler reste plus avantageux, et la version 2022 exigeait d'être en formation."),
  ("Les parents sont là pour ça.", "Tous les jeunes n'ont pas des parents qui peuvent aider ; c'est justement pour eux que 18,6 % des 18-29 ans sont pauvres."),
 ],
 questions=["Sais-tu qu'avant 25 ans, on n'a droit au RSA que si l'on a déjà travaillé deux ans à temps plein ?", "À ton avis, un étudiant sans aide de ses parents peut-il étudier correctement en travaillant à côté ?"],
 limites=["La version 2026 du programme a été lue via une page web résumée ; le texte exact des conditions (âge, formation) n'a pas pu être vérifié en entier.", "Les chiffrages datent de 2022 et ne correspondent pas forcément à la version actuelle.", "Le taux de pauvreté des 18-24 ans seuls n'est pas publié dans la source Insee lue (tranche 18-29 ans)."],
 publics={'convaincus': "Lis le programme : c'est un complément de revenu pour que les jeunes indépendants ne vivent pas sous le seuil de pauvreté, pas un salaire pour rester chez soi. En 2022, il fallait même être en formation. Aujourd'hui, un jeune de moins de 25 ans sans emploi n'a presque droit à rien, alors que près d'un sur cinq est pauvre.",
  'indecis': "La question du coût est légitime, et la mesure mérite un vrai débat. Mais elle part d'un fait : 18,6 % des 18-29 ans sont pauvres, et le RSA leur est presque fermé. Il s'agit d'éviter qu'un jeune doive abandonner ses études faute d'argent."},
 a_actualiser='2027-04-30', raison="Programme définitif pour la présidentielle 2027 et éventuels nouveaux chiffrages.",
))

