FICHES.append(fiche(
 id='gauche-caviar-lecons', affirmation="La gauche caviar donne des leçons de morale mais vit dans les beaux quartiers.", volet='politique', sous_theme='Gauche et pluralisme politique',
 mots_cles=['gauche caviar', 'bobos de gauche', 'gauche bobo', 'donneurs de lecons gauche', 'gauche beaux quartiers', 'gauche des riches', 'gauche bien pensante', 'gauche ne connait pas le peuple', 'gauche brahmane', 'qui vote a gauche'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Les beaux quartiers votent d'abord pour la droite et le centre : aux européennes 2024, la liste macroniste est en tête dans les communes aisées de l'Ouest parisien et la droite garde le 16e arrondissement. La gauche radicale fait ses meilleurs scores dans des banlieues populaires. Il est vrai que l'électorat de gauche est devenu plus diplômé et urbain. Mais même pour un militant aisé, l'attaque personnelle ne dit rien de la justesse de ses idées.",
 contexte="L'expression « gauche caviar » vise à disqualifier les défenseurs de l'égalité en les accusant d'hypocrisie. Elle est reprise aujourd'hui contre les « bobos » ou la gauche « donneuse de leçons ».",
 explication="Il faut regarder qui vote pour qui selon le revenu, le diplôme et le lieu de vie, puis distinguer la critique d'une personne de l'examen de ses arguments.",
 sources=[PA_IFOP_FOCUS_243_2024, PA_IPSOS_LEGISLATIVES_2024, PA_PIKETTY_BRAHMIN_2018, PA_ROUBAN_CEVIPOF_2024],
 faits=[
  fait("Aux européennes 2024, la liste de la majorité présidentielle arrive en tête dans les communes aisées des Hauts-de-Seine et des Yvelines et dans les beaux quartiers du centre de Paris ; la droite (LR) garde le 16e arrondissement.", 'pa_ifop_focus_243_2024', '2024', 'France', "Les beaux quartiers votent d'abord pour la droite et le centre.", 'etabli'),
  fait("La liste LFI arrive en tête dans des banlieues populaires : 58,1 % à La Courneuve, 54,5 % à Trappes, 48,4 % à Aubervilliers, 44,1 % à Grigny.", 'pa_ifop_focus_243_2024', '2024', 'France', "La gauche radicale est forte là où vivent les classes populaires.", 'etabli', '58,1 %'),
  fait("Aux législatives 2024, au-dessus de 3 000 € de revenu mensuel, le RN obtient 32 % et le NFP 26 % ; chez les personnes « aisées », NFP 28 % et Ensemble 27 %.", 'pa_ipsos_legislatives_2024', '2024', 'France', "Les électeurs aisés ne votent pas majoritairement à gauche.", 'estimation', '26 %'),
  fait("Fait défavorable : le NFP obtient 34 % chez les cadres et 37 % chez les diplômés de niveau bac+3, alors que 57 % des ouvriers votent RN au premier tour des législatives 2024.", 'pa_ipsos_legislatives_2024', '2024', 'France', "La gauche a perdu une large part du vote ouvrier : c'est un vrai défi pour elle.", 'estimation', '57 %'),
  fait("Fait défavorable : selon Thomas Piketty, le vote de gauche s'est déplacé depuis les années 1950-1960 des peu diplômés vers les plus diplômés, mais les hauts revenus et hauts patrimoines votent encore majoritairement à droite.", 'pa_piketty_brahmin_2018', '1950-2017', 'France, Royaume-Uni, États-Unis', "La gauche est devenue celle des diplômés, pas celle des riches.", 'interpretation'),
  fait("Aux européennes 2024, les listes de gauche ou écologistes recueillent 51 % chez les enseignants.", 'pa_rouban_cevipof_2024', '2024', 'France', "Une partie de l'électorat de gauche est diplômée sans être riche : enseignants, soignants, cadres du public.", 'estimation', '51 %'),
 ],
 court="Les beaux quartiers votent surtout à droite et au centre : en 2024, la liste macroniste gagne les communes aisées de l'Ouest parisien, la droite garde le 16e. La gauche radicale fait ses meilleurs scores à La Courneuve ou Trappes. Et une attaque contre la personne ne répond jamais à ses arguments.",
 moyen="Les chiffres contredisent l'image. Aux européennes 2024, la liste de la majorité présidentielle arrive en tête dans les communes aisées des Hauts-de-Seine et des Yvelines, et la droite garde le 16e arrondissement de Paris. La liste LFI fait 58,1 % à La Courneuve et 54,5 % à Trappes. Chez les électeurs qui gagnent plus de 3 000 € par mois, le RN fait mieux que le NFP.\n\nIl est vrai que la gauche attire beaucoup de diplômés : 37 % des bac+3 ont voté NFP en 2024. Mais un diplômé n'est pas forcément riche : enseignants, soignants, cadres du public. Et même un riche peut avoir raison de défendre l'égalité : on juge une idée sur ses preuves, pas sur l'adresse de celui qui la porte.",
 detaille="Le cliché de la « gauche caviar » suppose que la gauche serait le parti des riches. Les données électorales disent autre chose. Aux européennes 2024, selon l'Ifop, la liste macroniste arrive en tête dans les communes aisées des Hauts-de-Seine et des Yvelines et dans les beaux quartiers du centre de Paris, et la droite garde le 16e arrondissement. À l'inverse, la liste LFI obtient 58,1 % à La Courneuve, 54,5 % à Trappes et 48,4 % à Aubervilliers. Aux législatives, chez les électeurs gagnant plus de 3 000 € par mois, le RN obtient 32 % et le NFP 26 %.\n\nIl faut reconnaître une évolution réelle. Thomas Piketty a montré que le vote de gauche, autrefois celui des ouvriers peu diplômés, s'est déplacé vers les plus diplômés, tandis que les hauts revenus et patrimoines votent toujours à droite. En 2024, le NFP fait 37 % chez les bac+3 et 34 % chez les cadres, alors que 57 % des ouvriers votent RN. C'est un défi pour la gauche, qui doit reconquérir les classes populaires. Mais être diplômé ne veut pas dire vivre dans les beaux quartiers : beaucoup sont enseignants ou soignants.\n\nSurtout, l'argument est une attaque contre la personne. Qu'un défenseur de l'impôt sur la fortune soit riche ne rend pas l'impôt injuste ; qu'un élu d'extrême droite soit fortuné ne rend pas son programme populaire. Cette accusation sert souvent à éviter le débat de fond : qui gagne, qui perd, avec quelles politiques ?",
 empathie="Il est agaçant d'entendre des leçons de gens qui semblent ne pas vivre les mêmes difficultés que soi. Ce sentiment de mépris de classe existe ; il mérite d'être pris au sérieux.",
 legitimes=["L'électorat de gauche est devenu plus diplômé et plus urbain, et la gauche a perdu une large partie du vote ouvrier.", "Certains responsables de gauche ont un mode de vie éloigné de celui des classes populaires."],
 contre=[
  ("Les bobos des centres-villes votent à gauche.", "Une partie des diplômés urbains, oui. Mais les quartiers les plus riches votent surtout pour la droite et le centre, et la gauche radicale fait ses meilleurs scores dans les banlieues populaires."),
  ("Ils devraient d'abord donner leur argent.", "Une idée se juge sur ses effets, pas sur la vertu de celui qui la défend. La gauche propose justement de faire contribuer les plus riches par l'impôt, pas par la charité individuelle."),
 ],
 questions=["Sais-tu dans quelles communes la liste LFI a fait ses meilleurs scores en 2024 ?", "Si un patron riche défend une idée, est-ce que sa fortune suffit à la rendre fausse ?"],
 limites=["Les chiffres par revenu et profession viennent de sondages sortie des urnes, avec une marge d'erreur non publiée dans les articles lus.", "Le travail de Thomas Piketty a été lu via son résumé ; les données s'arrêtent à 2017.", "Aucune source lue ne compare le patrimoine des élus selon leur parti."],
 publics={'convaincus': "Regarde les résultats : en 2024, les communes aisées de l'Ouest parisien et les beaux quartiers votent pour la droite et le centre, pas pour la gauche. La gauche radicale gagne à La Courneuve ou Trappes. Et si un élu de gauche est riche, ça ne rend pas fausse l'idée de taxer les grandes fortunes.",
  'indecis': "Le sentiment de recevoir des leçons de gens éloignés de sa vie est compréhensible, et la gauche a perdu une partie du vote ouvrier. Mais les électeurs les plus aisés votent surtout à droite et au centre. Le plus utile est de juger les propositions sur ce qu'elles changent pour toi."},
 a_actualiser='2027-07-31', raison="Sociologie des électorats après la présidentielle et les législatives de 2027.",
))

