PB_BELGA_EUTH_2025 = ('pb_belga_euth_2025', src('Number of euthanasia cases in Belgium rose by 12 per cent in 2025', 'Belga News Agency (chiffres de la Commission fédérale de contrôle et d\'évaluation de l\'euthanasie)', '2026 (données 2025)',
  'https://www.belganewsagency.eu/number-of-euthanasia-cases-in-belgium-rose-by-12-per-cent-in-2025',
  "4 486 euthanasies en Belgique en 2025, en hausse de plus de 12 % sur 2024. 73,7 % des patients avaient plus de 70 ans et 45 % plus de 80 ans. Cancer : environ la moitié des patients ; polypathologies : 30 % ; troubles psychiatriques : 1,6 % ; troubles cognitifs : 1,7 %. Dans trois cas sur quatre, le décès était attendu à brève échéance ; les euthanasies de patients non en fin de vie sont passées de 923 en 2024 à 1 117 en 2025.",
  "Agence de presse belge reprenant le rapport de la commission officielle de contrôle.", 'secondaire'))
PB_OHA_DWDA_2025 = ('pb_oha_dwda_2025', src("Report: Death with Dignity Act prescriptions continued rise in 2025", 'Oregon Health Authority', '2 avril 2026',
  'https://www.oregon.gov/oha/ERD/Pages/Report-Death-with-Dignity-Act-prescriptions-continued-rise-in-2025-04.02.2026.aspx',
  "637 prescriptions en 2025 (609 en 2024) et 400 décès (421 en 2024). Condition : « A diagnosis of a terminal illness that will lead to death within six months », avoir 18 ans ou plus et être capable de prendre ses décisions de santé. 88 % des participants avaient 65 ans ou plus ; cancer 61 %, maladies neurologiques 14 %, cardiaques 11 %. Motifs les plus cités : perte d'autonomie (89 %), moindre capacité à faire ce qui rend la vie agréable (89 %), perte de dignité (65 %).",
  "Autorité sanitaire officielle de l'Oregon ; rapport annuel.", 'primaire'))
PB_HANDICAP_FR_AAM = ('pb_handicap_fr_aam', src('Aide à mourir et handicap : des débats au Sénat sous tension', 'Handicap.fr (informations.handicap.fr)', '22 janvier 2026, mis à jour le 29 janvier 2026',
  'https://informations.handicap.fr/a-aide-a-mourir-et-handicap-des-debats-au-senat-sous-tension-38727.php',
  "Le Sénat a rejeté le texte par 181 voix contre 122. L'association Les Éligibles et leurs aidants juge les critères « flous et extensibles », relève que les personnes avec une déficience intellectuelle « demeurent éligibles, sans garanties renforcées » et critique un « temps de réflexion de deux jours ». Le Collectif handicaps (54 associations) reste neutre mais vigilant : « une personne handicapée va-t-elle se convaincre que la meilleure solution serait de demander l'aide à mourir ? » ; la question « reste celle de l'évaluation du discernement, et de qui en décide ».",
  "Média spécialisé sur le handicap ; rapporte les positions d'associations (texte du Sénat, janvier 2026).", 'secondaire'))

FICHES.append(fiche(
 id='aide-a-mourir-euthanasie', affirmation="La loi sur l'aide à mourir va permettre d'euthanasier les vieux et les handicapés.", volet='droits', sous_theme='Libertés publiques',
 mots_cles=['aide a mourir', 'loi fin de vie', 'euthanasie vieux', 'euthanasie handicapes', 'suicide assiste france', 'loi falorni', 'on va tuer les vieux', 'euthanasie belgique', 'droit a mourir', 'fin de vie 2026'],
 verdict='trompeur', fiabilite='etabli',
 resume="Trompeur. La loi du 18 août 2026 ne vise ni l'âge ni le handicap. Elle ouvre un droit à une personne majeure, atteinte d'une maladie grave et incurable qui engage son pronostic vital, en phase avancée ou terminale, qui souffre et qui le demande elle-même, avec un discernement intact. Avoir 85 ans ou un handicap ne suffit pas. En revanche, des associations de personnes handicapées ont exprimé des craintes sérieuses sur les pressions et l'évaluation du discernement.",
 contexte="Après plus d'un an de navette, le Parlement a adopté définitivement la loi le 15 juillet 2026 (291 voix contre 241). Le Conseil constitutionnel l'a validée avec trois réserves le 14 août 2026 ; elle a été promulguée le 18 août 2026.",
 explication="Il faut lire les conditions d'accès dans le texte, regarder qui décide (le patient seul, puis un médecin après une procédure collégiale) et comparer avec les pays qui pratiquent l'aide à mourir depuis longtemps.",
 sources=[PB_SENAT_DOSSIER_AAM, PB_LCP_AAM_2026, PB_WEKA_AAM_LOI, PB_BELGA_EUTH_2025, PB_OHA_DWDA_2025, PB_HANDICAP_FR_AAM],
 faits=[
  fait("La loi n° 2026-794 du 18 août 2026 a été adoptée définitivement par l'Assemblée nationale le 15 juillet 2026, après trois rejets du Sénat, puis jugée conforme à la Constitution le 14 août 2026.", 'pb_senat_dossier_aam', '2025-2026', 'France', "C'est un texte voté par le Parlement et contrôlé par le Conseil constitutionnel.", 'etabli'),
  fait("Les conditions sont cumulatives : être majeur, être atteint d'une « affection grave et incurable » qui engage le pronostic vital, souffrir de cette affection, et être « apte à manifester sa volonté de façon libre et éclairée ».", 'pb_lcp_aam_2026', '2026', 'France', "L'âge et le handicap ne sont pas des critères : la demande vient de la personne malade elle-même.", 'etabli'),
  fait("Le médecin doit rendre une décision motivée dans les quinze jours après une procédure collégiale ; le patient doit confirmer après au moins deux jours de réflexion ; sa volonté est vérifiée le jour même et toute pression est signalée au parquet. La souffrance psychologique seule ne suffit pas.", 'pb_weka_aam_loi', '2026', 'France', "La loi prévoit des verrous contre les décisions imposées.", 'etabli', '15 jours'),
  fait("En Oregon, l'aide à mourir est réservée aux malades en phase terminale (décès attendu dans les six mois) : 400 décès en 2025 ; 88 % des personnes avaient 65 ans ou plus et 61 % un cancer.", 'pb_oha_dwda_2025', '2025', 'Oregon (États-Unis)', "Dans un modèle restrictif, ce sont surtout des malades du cancer en fin de vie qui y recourent.", 'etabli', '400'),
  fait("Fait défavorable : en Belgique, où la loi ne réserve pas l'euthanasie à la fin de vie, 4 486 euthanasies ont eu lieu en 2025 ; 73,7 % des patients avaient plus de 70 ans, 30 % souffraient de polypathologies, et 1 117 n'étaient pas en fin de vie.", 'pb_belga_euth_2025', '2025', 'Belgique', "Les craintes d'élargissement s'appuient sur des exemples réels ; la loi française est toutefois plus restrictive.", 'etabli', '4 486'),
  fait("Fait défavorable : des associations de personnes handicapées ont jugé les critères « flous et extensibles » et redouté qu'une personne handicapée se convainque de demander l'aide à mourir ; le Collectif handicaps (54 associations) est resté neutre mais vigilant sur l'évaluation du discernement.", 'pb_handicap_fr_aam', '2026', 'France', "Ces inquiétudes sont légitimes et doivent guider l'application de la loi.", 'etabli'),
 ],
 court="Faux dans les termes : la loi ne vise ni l'âge ni le handicap. Il faut être majeur, atteint d'une maladie grave et incurable qui engage le pronostic vital, souffrir, et le demander soi-même avec un discernement intact.",
 moyen="La loi du 18 août 2026 crée un droit à l'aide à mourir pour des malades majeurs, atteints d'une affection grave et incurable qui engage leur pronostic vital, en phase avancée ou terminale, qui souffrent et qui en font eux-mêmes la demande. Un médecin décide après une procédure collégiale, le patient confirme après un délai de réflexion, et toute pression est signalée au parquet.\n\nÊtre âgé ou handicapé ne donne donc aucun « droit » à être euthanasié, et personne ne peut le demander à la place de quelqu'un. Les craintes des associations de personnes handicapées sur les pressions sociales sont réelles et doivent être prises au sérieux ; la réponse, c'est des contrôles stricts et des soins palliatifs accessibles partout.",
 detaille="Le texte a eu un parcours long : adopté trois fois par l'Assemblée, rejeté trois fois par le Sénat, il a été voté définitivement le 15 juillet 2026 par 291 voix contre 241. Le Conseil constitutionnel l'a validé le 14 août 2026 avec trois réserves, dont une garantie pour les majeurs protégés. La loi n° 2026-794 date du 18 août 2026.\n\nLes conditions sont cumulatives : être majeur ; être français ou résider de façon stable et régulière en France ; être atteint d'une affection grave et incurable qui engage le pronostic vital, en phase avancée ou terminale ; souffrir de cette affection ; être apte à exprimer une volonté libre et éclairée. La souffrance psychologique seule ne suffit pas. Le médecin rend une décision motivée dans les quinze jours après avis collégial ; le patient doit confirmer après au moins deux jours ; l'auto-administration est la règle. L'âge et le handicap ne figurent nulle part parmi les critères.\n\nLes comparaisons montrent deux modèles. En Oregon, réservé aux malades qui ont moins de six mois à vivre, il y a eu 400 décès en 2025, surtout des personnes atteintes de cancer. En Belgique, la loi est plus large : 4 486 euthanasies en 2025, dont plus de mille chez des personnes qui n'étaient pas en fin de vie. C'est pour cela que des associations de personnes handicapées demandent de la vigilance. Leur inquiétude est légitime : elle plaide pour une application stricte et pour des soins palliatifs et un accompagnement à domicile dignes, pas pour la peur.",
 empathie="Penser qu'on pourrait pousser un parent âgé ou une personne handicapée vers la mort, c'est terrifiant. Cette peur dit quelque chose de juste : la valeur d'une vie ne dépend ni de l'âge ni de l'autonomie.",
 legitimes=["Des associations de personnes handicapées craignent des pressions sociales et une évaluation fragile du discernement.", "En Belgique, l'euthanasie concerne aussi des personnes qui ne sont pas en fin de vie, ce qui alimente la crainte d'un élargissement.", "Un droit à mourir sans soins palliatifs accessibles partout pourrait devenir un choix contraint."],
 contre=[
  ("On va s'en servir pour faire des économies sur les retraités.", "La demande doit venir du patient lui-même, être confirmée et vérifiée jusqu'au dernier moment ; toute pression est signalée au parquet. Personne d'autre ne peut demander à sa place."),
  ("En Belgique, ça a dérapé.", "La loi belge ne réserve pas l'euthanasie à la fin de vie ; la loi française exige une maladie grave et incurable qui engage le pronostic vital, en phase avancée ou terminale."),
  ("Les handicapés mentaux pourront être euthanasiés.", "Il faut un discernement intact au moment de la demande ; pour un majeur protégé, le Conseil constitutionnel impose de tenir compte de la personne chargée de sa protection. Les associations demandent des garanties renforcées : c'est un vrai débat d'application."),
 ],
 questions=["Savais-tu que l'âge et le handicap ne figurent pas parmi les conditions de la loi ?", "Qu'est-ce qui te rassurerait le plus : des contrôles plus stricts, ou des soins palliatifs disponibles partout ?"],
 limites=["Le texte de la loi n'a pas été lu sur Légifrance : les conditions viennent de deux comptes rendus de presse (LCP, Weka) ; ils divergent sur la mention de la souffrance « physique ou psychologique », Weka précisant que la souffrance psychologique seule ne suffit pas.", "Les décrets d'application et la date d'entrée en vigueur effective n'ont pas été vérifiés.", "Les chiffres belges viennent d'une dépêche de presse reprenant la commission officielle ; le rapport lui-même n'a pas été ouvert.", "Aucune donnée française d'application n'existe encore."],
 publics={'convaincus': "Relis les conditions : être majeur, malade d'une affection grave et incurable qui engage ta vie, souffrir, et le demander toi-même, avec toute ta tête. Avoir 85 ans ou être en fauteuil ne donne accès à rien. Les vraies questions, ce sont les contrôles et les soins palliatifs, et là-dessus on peut être d'accord.",
  'indecis': "Ta crainte est partagée par des associations de personnes handicapées, et elle mérite d'être entendue. La loi française est plus stricte que la loi belge : elle exige une maladie grave et incurable qui engage le pronostic vital, et la demande ne peut venir que du patient. La vigilance doit porter sur son application et sur l'accès aux soins palliatifs."},
 a_actualiser='2027-06-30', raison="Entrée en vigueur, décrets d'application et premiers chiffres de la commission de contrôle.",
))

# 2 ── PMA pour toutes et absence de père ───────────────────────────────────
PB_LCP_PMA_2026 = ('pb_lcp_pma_2026', src("« PMA pour toutes » : cinq ans après l'entrée en vigueur de la loi, un bilan en demi-teinte", 'LCP (La Chaîne parlementaire)', '28 septembre 2026',
  'https://lcp.fr/actualites/pma-pour-toutes-cinq-ans-apres-l-entree-en-vigueur-de-la-loi-un-bilan-en-demi-teinte',
  "Le décret d'application date du 28 septembre 2021. Entre août 2021 et fin 2025, 43 450 tentatives de PMA avec don de spermatozoïdes pour des couples de femmes ou des femmes seules, soit une multiplication par six. Ces tentatives représentaient 3 % du total en 2019 et 11,6 % en 2023. Délai d'attente pour un don de spermatozoïdes : environ un an en février 2022, 17,7 mois en 2025 ; de 8 à 28 mois selon les territoires. 105 centres autorisés. Chiffres pour l'essentiel issus de l'Agence de la biomédecine et d'un rapport de l'Opecst.",
  "Chaîne parlementaire ; bilan s'appuyant sur l'Agence de la biomédecine et l'Office parlementaire d'évaluation des choix scientifiques et technologiques.", 'secondaire'))
PB_VIDAL_ORIGINES_2025 = ('pb_vidal_origines_2025', src('Les personnes nées de PMA auront désormais toutes accès à leurs origines', 'Vidal', '1er avril 2025',
  'https://www.vidal.fr/actualites/34104-les-personnes-nees-de-pma-auront-desormais-toutes-acces-a-leurs-origines.html',
  "Depuis septembre 2022, chaque nouveau donneur doit consentir à la communication future de ses « données identifiantes et non identifiantes » ; les personnes nées d'un don y ont accès une fois majeures. La fin de la période transitoire « prend effet pour tous les enfants à naître ». Entre 2022 et fin janvier 2025, 701 adultes issus d'un don ont saisi la CAPADD et 73 ont obtenu des données. Plus de 1 000 candidats donneurs de spermatozoïdes en 2024, contre 676 en 2023. Fin 2024, plus de 10 600 femmes en attente : 45 % de femmes seules, 38 % de femmes en couple avec une femme, 17 % en couple avec un homme.",
  "Base d'information médicale de référence, reprenant le ministère de la Santé et l'Agence de la biomédecine.", 'secondaire'))
PB_CAM_SOLO_MOTHERS = ('pb_cam_solo_mothers', src("Single Mothers by Choice: Mother–Child Relationships and Children's Psychological Adjustment", 'Université de Cambridge (Centre for Family Research), dépôt institutionnel Apollo', 'article publié dans une revue de psychologie de la famille (ISSN 1939-1293)',
  'https://www.repository.cam.ac.uk/handle/1810/253324',
  "Comparaison de 51 familles de mères seules par choix et de 52 familles biparentales, avec un enfant de 4 à 9 ans conçu par don de sperme (entretiens, observations, questionnaires des mères, des enfants et des enseignants). « There were no differences in parenting quality between family types », sauf un conflit mère-enfant plus faible chez les mères seules ; « Neither were there differences in child adjustment ». Les difficultés financières et le stress parental sont associés aux problèmes de l'enfant dans les deux types de familles. La monoparentalité en soi « does not result in psychological problems for children ».",
  "Étude universitaire évaluée par les pairs ; petit échantillon britannique, enfants jeunes.", 'etude'))
PB_CAM_FAMILIES_2015 = ('pb_cam_families_2015', src('Families with a difference: the reality behind the hype', 'Université de Cambridge', '12 mars 2015',
  'https://cam.ac.uk/node/144932',
  "Présentation des travaux de Susan Golombok (Centre for Family Research) et du livre Modern Families (2015) : la qualité des relations familiales compte davantage que le nombre, le sexe ou l'orientation sexuelle des parents, ou le recours à la procréation assistée. Les enfants à qui l'on parle tôt de leur conception par don l'acceptent sans détresse ; l'apprendre à l'adolescence ou à l'âge adulte semble plus difficile.",
  "Communication officielle d'université résumant un programme de recherche.", 'secondaire'))
PB_ALLODOC_ACADEMIE_2019 = ('pb_allodoc_academie_2019', src("PMA : « Les arguments de l'Académie de médecine sont idéologiquement biaisés »", 'Allô Docteurs (France Télévisions)', '23 septembre 2019',
  'https://www.allodocteurs.fr/se-soigner/recherche/ethique-bioethique/pma-les-arguments-de-lacademie-de-medecine-sont-ideologiquement-biaises_27873.html',
  "Le 21 septembre 2019, l'Académie nationale de médecine a qualifié la conception délibérée d'un enfant sans père de « rupture anthropologique majeure », « pas sans risques » pour son développement psychologique, tout en reconnaissant « la légitimité du désir de maternité chez toute femme ». L'académicien Philippe Froguel juge le rapport « scientifiquement bâclé » et rappelle que les études internationales n'ont pas montré d'effet négatif, la plus grande ayant suivi des enfants pendant « 25 ans ». La ministre de la Santé a jugé faux le lien direct entre structure familiale et développement de l'enfant.",
  "Média santé du service public ; rend compte d'une controverse scientifique.", 'secondaire'))

FICHES.append(fiche(
 id='pma-pour-toutes-pere', affirmation="La PMA pour toutes prive les enfants de père.", volet='droits', sous_theme='Droits des personnes LGBT',
 mots_cles=['pma pour toutes', 'pma sans pere', 'enfants sans pere', 'pma lesbiennes', 'pma femmes seules', 'loi bioethique 2021', 'droit a un pere', 'acces aux origines', 'don de sperme anonymat', 'pma couples de femmes'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Les enfants nés d'une PMA dans un couple de femmes ou chez une femme seule n'ont pas de père légal, c'est vrai. Mais ils ne sont « privés » de rien qu'ils auraient eu autrement : sans ce projet, ils ne seraient pas nés. Les études disponibles ne montrent pas de différence d'adaptation avec les autres enfants, et depuis 2022 tous les nouveaux donneurs acceptent que l'enfant devenu majeur puisse connaître son identité.",
 contexte="La loi de bioéthique de 2021 a ouvert la PMA aux couples de femmes et aux femmes seules ; le décret date du 28 septembre 2021. En 2019, l'Académie de médecine avait émis des réserves sur l'absence de père.",
 explication="Il faut distinguer le père (un rôle familial et juridique) du donneur, regarder ce que disent les études sur le développement des enfants, et ce que la loi a changé pour l'accès aux origines.",
 sources=[PB_LCP_PMA_2026, PB_VIDAL_ORIGINES_2025, PB_CAM_SOLO_MOTHERS, PB_CAM_FAMILIES_2015, PB_ALLODOC_ACADEMIE_2019],
 faits=[
  fait("Entre août 2021 et fin 2025, 43 450 tentatives de PMA avec don de spermatozoïdes ont concerné des couples de femmes ou des femmes seules, une multiplication par six ; elles représentaient 11,6 % des tentatives de PMA en 2023.", 'pb_lcp_pma_2026', '2021-2025', 'France', "Il s'agit d'enfants très désirés, dans des familles qui ont mûri leur projet.", 'etabli', '43 450'),
  fait("Fin 2024, plus de 10 600 femmes attendaient un don : 45 % de femmes seules, 38 % de femmes en couple avec une femme, 17 % de femmes en couple avec un homme.", 'pb_vidal_origines_2025', '2024', 'France', "Les couples hétérosexuels ont aussi recours au don de sperme : l'enfant n'a alors pas de lien génétique avec son père, sans que personne ne parle d'enfant « privé de père ».", 'etabli', '10 600'),
  fait("Depuis septembre 2022, chaque nouveau donneur doit accepter que ses données identifiantes et non identifiantes soient communiquées à l'enfant devenu majeur ; entre 2022 et janvier 2025, 701 adultes nés d'un don ont saisi la commission d'accès aux origines.", 'pb_vidal_origines_2025', '2022-2025', 'France', "La loi de 2021 permet à ces enfants de connaître leurs origines, ce que l'anonymat interdisait avant.", 'etabli', '701'),
  fait("Une étude de Cambridge comparant 51 familles de mères seules par choix et 52 familles biparentales, avec des enfants de 4 à 9 ans conçus par don, ne trouve pas de différence de qualité parentale ni d'adaptation des enfants ; les difficultés financières et le stress parental comptent davantage.", 'pb_cam_solo_mothers', 'années 2010', 'Royaume-Uni', "Ce qui pèse sur l'enfant, c'est la précarité et le stress, pas l'absence de père en soi.", 'interpretation'),
  fait("Fait défavorable : en septembre 2019, l'Académie nationale de médecine a jugé la conception délibérée d'un enfant sans père « pas sans risques » pour son développement psychologique ; elle a été contestée par certains de ses membres et par la ministre de la Santé.", 'pb_allodoc_academie_2019', '2019', 'France', "Une institution médicale a exprimé des réserves ; elles ne reposaient pas sur une étude citée.", 'debat'),
  fait("Selon les travaux du Centre for Family Research de Cambridge, la qualité des relations compte plus que la structure familiale ; parler tôt à l'enfant de sa conception par don l'aide à l'accepter.", 'pb_cam_families_2015', '2015', 'Royaume-Uni', "Le bien-être de l'enfant dépend surtout de la manière dont il est élevé.", 'interpretation'),
 ],
 court="Ces enfants n'ont pas de père légal, mais ils n'ont été « privés » de rien : sans PMA, ils ne seraient pas nés. Les études ne montrent pas qu'ils vont moins bien, et la loi leur permet maintenant de connaître leur donneur à leur majorité.",
 moyen="Depuis 2021, les couples de femmes et les femmes seules peuvent recourir à la PMA. Entre août 2021 et fin 2025, plus de 43 000 tentatives avec don de sperme les ont concernées. Ces enfants grandissent sans père, mais dans des familles qui les ont longuement désirés, avec un ou deux parents.\n\nLes études disponibles, comme celle de Cambridge sur les mères seules par choix, ne montrent pas de différence d'adaptation des enfants : ce qui pèse, c'est la précarité et le stress parental. Et depuis 2022, tous les nouveaux donneurs acceptent que l'enfant majeur puisse connaître leur identité.",
 detaille="La loi de bioéthique de 2021 a ouvert la PMA aux couples de femmes et aux femmes seules. Entre août 2021 et fin 2025, 43 450 tentatives avec don de sperme les ont concernées, et fin 2024 plus de 10 600 femmes attendaient un don. L'attente atteint environ 17,7 mois en moyenne en 2025, avec de fortes inégalités entre territoires.\n\n« Priver de père » suppose qu'un père existait. Or ces enfants n'auraient pas été conçus sans ce projet. Les recherches menées notamment à Cambridge ne trouvent pas de différence de qualité parentale ni d'adaptation des enfants entre familles de mères seules par choix et familles biparentales ; ce qui compte, c'est la qualité des relations, la stabilité et les ressources. En 2019, l'Académie de médecine avait exprimé des réserves, mais elles ont été contestées en son sein, faute d'étude à l'appui.\n\nLa question des origines est sérieuse, et la loi y a répondu : depuis septembre 2022, les donneurs consentent à ce que l'enfant majeur accède à leur identité. Pour les personnes nées sous l'anonymat, la procédure reste longue. La vraie urgence, c'est de réduire l'attente et les inégalités d'accès, pas de revenir sur un droit.",
 empathie="On peut avoir grandi avec un père qui a beaucoup compté, et avoir du mal à imaginer une enfance sans lui. Cette émotion est sincère ; elle mérite qu'on regarde comment vont réellement ces enfants.",
 legitimes=["L'Académie de médecine a émis des réserves en 2019.", "Les études portent souvent sur de petits échantillons et des enfants jeunes.", "Connaître ses origines est un besoin réel pour beaucoup de personnes nées d'un don."],
 contre=[
  ("Un enfant a besoin d'un père et d'une mère.", "Les études disponibles ne montrent pas de différence d'adaptation ; ce qui compte, c'est la qualité des relations, la stabilité et les ressources de la famille."),
  ("Ces enfants ne sauront jamais d'où ils viennent.", "Depuis 2022, chaque nouveau donneur accepte que l'enfant majeur connaisse son identité ; c'était impossible avant la loi de 2021."),
 ],
 questions=["Est-ce qu'on dirait d'un enfant élevé par une mère veuve qu'il a été « privé » de père par l'État ?", "Pour toi, qu'est-ce qui compte le plus pour qu'un enfant aille bien ?"],
 limites=["La loi de 2021 n'a pas été lue sur Légifrance ou Vie publique (page inaccessible) ; les dispositions sont décrites d'après des articles de presse.", "Aucune étude française de suivi des enfants nés de la PMA pour toutes n'a été trouvée : ces enfants ont au plus cinq ans.", "L'étude de Cambridge porte sur un petit échantillon britannique d'enfants de 4 à 9 ans ; sa date de publication n'apparaît pas sur la page du dépôt.", "La fiche mariage-pour-tous-famille traite plus largement des études sur les familles homoparentales."],
 publics={'convaincus': "Ces enfants n'avaient pas de père qu'on leur aurait retiré : sans PMA, ils ne seraient pas nés. Les études ne montrent pas qu'ils vont moins bien, et la loi leur permet désormais de connaître leur donneur à 18 ans. Ce qui abîme les enfants, c'est la précarité et les conflits, pas le fait d'avoir deux mères.",
  'indecis': "C'est normal de se poser la question du père. Les recherches disponibles, encore limitées, montrent que ces enfants vont aussi bien que les autres quand la famille est stable. Et depuis 2022, ils pourront connaître l'identité de leur donneur à leur majorité."},
 a_actualiser='2027-09-30', raison="Nouveau bilan de l'Agence de la biomédecine et éventuelle révision de la loi de bioéthique.",
))

# 3 ── MeToo et fausses accusations de viol ─────────────────────────────────
PB_SSMSI_IR33_2024 = ('pb_ssmsi_ir33_2024', src('Les violences sexuelles hors cadre familial enregistrées par les services de sécurité en 2023 (Interstats Info Rapide n° 33)', 'SSMSI (ministère de l\'Intérieur)', 'mars 2024',
  'https://interieur.gouv.fr/content/download/136125/1077745/file/IR33-Violences sexuelles hors cadre familial.pdf',
  "83 456 victimes de violences sexuelles hors cadre familial enregistrées en 2023 (114 000 au total avec l'intrafamilial) ; 85 % sont des femmes. Selon l'enquête Vécu et ressenti en matière de sécurité 2022, « seules 2 % des personnes de 18 à 74 ans victimes de violences sexuelles hors cadre familial portent plainte auprès des forces de sécurité » (6 % pour les violences physiques). 54 586 mis en cause en 2023 : 96 % d'hommes, 87 % de nationalité française, 28 % de mineurs.",
  "Service statistique ministériel de la sécurité intérieure.", 'primaire'))
PB_SSMSI_IA64_2024 = ('pb_ssmsi_ia64_2024', src('Insécurité et délinquance en 2023 : une première photographie (Interstats Analyse n° 64)', 'SSMSI (ministère de l\'Intérieur)', 'janvier 2024',
  'https://interieur.gouv.fr/content/download/135975/1076724/file/IA-64_V3-3.pdf',
  "Le nombre de victimes de violences sexuelles enregistrées « augmente nettement en 2023 (+8 %), après une forte hausse en 2022 (+12 %) » et « se situe sur une tendance à la hausse depuis 2017 ». Le SSMSI l'explique par l'évolution du dépôt de plainte après l'affaire Weinstein et les mouvements « en faveur de la libération de la parole des victimes », et par l'« amélioration des conditions d'accueil des victimes ». La part des faits commis plus de 5 ans avant leur enregistrement passe de 13 % en 2018 à 19 % en 2023.",
  "Service statistique ministériel ; bilan annuel.", 'primaire'))
PB_IPP_NOTE107_2024 = ('pb_ipp_note107_2024', src('Le traitement judiciaire des violences sexuelles et conjugales en France (Note IPP n° 107)', 'Institut des politiques publiques (IPP), Maëlle Stricot', 'avril 2024',
  'https://www.ipp.eu/wp-content/uploads/2024/04/Note_IPP_Violences_aux_femmes-5.pdf',
  "Affaires traitées par les parquets entre 2012 et 2022 : « le taux de non-poursuite est élevé et concerne 83 % des violences sexuelles », contre 73 % des violences conjugales et 84 % des autres atteintes à la personne. Le motif principal est l'infraction « insuffisamment caractérisée » (56 % des classements pour violences sexuelles). La part des viols non poursuivis passe de 82 % à 92 % sur la période étudiée. « Cela ne signifie pas que l'infraction n'a pas eu lieu » : les faits n'ont pas pu être clairement établis ou les preuves ont été jugées insuffisantes.",
  "Institut de recherche économique indépendant (École d'économie de Paris) ; données du ministère de la Justice.", 'etude'))
PB_LISAK_2010 = ('pb_lisak_2010', src('False Allegations of Sexual Assault: An Analysis of Ten Years of Reported Cases (Lisak, Gardinier, Nicksa, Cote, Violence Against Women, vol. 16, n° 12)', 'Office of Justice Programs (ministère de la Justice des États-Unis), notice NCJ 233292', 'décembre 2010',
  'https://ojp.gov/ncjrs/virtual-library/abstracts/false-allegations-sexual-assualt-analysis-ten-years-reported-cases',
  "Étude de 136 agressions sexuelles signalées sur dix ans à une grande université du nord-est des États-Unis : huit cas (5,9 %) ont été classés comme fausses allégations. Au vu des travaux antérieurs, les auteurs estiment que « the prevalence of false allegations is between 2 percent and 10 percent ».",
  "Notice officielle résumant un article scientifique évalué par les pairs ; terrain américain.", 'etude'))
PB_PSMAG_2018 = ('pb_psmag_2018', src('False Reports of Sexual Assault Are Rare. But Why Is There So Little Reliable Data About Them?', 'Pacific Standard (Emily Moon)', '5 octobre 2018',
  'https://psmag.com/news/false-reports-of-sexual-assault-are-rare-but-why-is-there-so-little-reliable-data-about-them',
  "La méta-analyse de Lisak (2010) situe les fausses déclarations entre 2 et 10 % des agressions sexuelles signalées. Une plainte classée « unfounded » par la police n'a pas forcément été prouvée fausse, ce qui gonfle certains chiffres ; les pratiques d'enregistrement varient fortement ; une étude estimant la prévalence à 41 % est jugée erronée. Plusieurs chercheurs soulignent l'absence de consensus sur la prévalence réelle.",
  "Magazine américain d'analyse ; synthèse des études et de leurs limites.", 'secondaire'))

FICHES.append(fiche(
 id='metoo-fausses-accusations', affirmation="Avec MeToo, les fausses accusations de viol sont fréquentes.", volet='securite', sous_theme='Violences sexuelles',
 mots_cles=['metoo fausses accusations', 'fausses accusations de viol', 'fausse plainte viol', 'balance ton porc', 'denonciation calomnieuse', 'les femmes mentent', 'plainte viol classee sans suite', 'presomption d innocence metoo', 'chasse aux sorcieres metoo', 'accuse a tort viol'],
 verdict='contredit', fiabilite='estimation',
 resume="Faux. Les études les plus citées estiment les fausses allégations entre 2 et 10 % des agressions sexuelles signalées, et elles ne portent que sur les faits déclarés. Or en France, seules 2 % des victimes de violences sexuelles hors cadre familial portent plainte. Le vrai problème est l'inverse : la grande majorité des violences ne sont jamais signalées, et plus de huit plaintes sur dix ne sont pas poursuivies, souvent faute de preuves, pas parce qu'elles sont fausses.",
 contexte="Depuis l'affaire Weinstein en 2017 et le mouvement #MeToo, les plaintes pour violences sexuelles augmentent en France. Certains y voient une vague de fausses accusations.",
 explication="Il faut distinguer une fausse accusation (prouvée fausse), une plainte classée sans suite (faits non établis) et une violence jamais déclarée, puis comparer leurs ordres de grandeur.",
 sources=[PB_SSMSI_IR33_2024, PB_SSMSI_IA64_2024, PB_IPP_NOTE107_2024, PB_LISAK_2010, PB_PSMAG_2018],
 faits=[
  fait("Selon l'enquête de victimation du ministère de l'Intérieur, « seules 2 % des personnes de 18 à 74 ans victimes de violences sexuelles hors cadre familial portent plainte ».", 'pb_ssmsi_ir33_2024', '2022', 'France', "L'immense majorité des violences sexuelles ne donne lieu à aucune accusation.", 'estimation', '2 %'),
  fait("Les victimes de violences sexuelles enregistrées augmentent depuis 2017 ; le SSMSI relie cette hausse à la libération de la parole après l'affaire Weinstein et à un meilleur accueil des victimes. Les faits anciens de plus de cinq ans passent de 13 % des enregistrements en 2018 à 19 % en 2023.", 'pb_ssmsi_ia64_2024', '2017-2023', 'France', "MeToo a fait sortir des violences restées cachées, y compris anciennes.", 'etabli', '+8 %'),
  fait("Entre 2012 et 2022, 83 % des affaires de violences sexuelles n'ont pas été poursuivies, surtout pour infraction « insuffisamment caractérisée » ; l'IPP précise que « cela ne signifie pas que l'infraction n'a pas eu lieu ».", 'pb_ipp_note107_2024', '2012-2022', 'France', "Un classement sans suite n'est pas une preuve de mensonge.", 'etabli', '83 %'),
  fait("Une étude américaine de 2010 sur dix ans de signalements dans une université a classé 5,9 % des cas comme fausses allégations ; avec les travaux antérieurs, les auteurs situent la proportion entre 2 et 10 %.", 'pb_lisak_2010', 'dix ans avant 2010', 'États-Unis', "Les fausses accusations existent mais restent minoritaires parmi les faits signalés.", 'estimation', '2 à 10 %'),
  fait("Fait défavorable : les chiffres sur les fausses accusations sont fragiles ; les définitions et les pratiques policières varient, et plusieurs chercheurs jugent la prévalence réelle difficile à établir. Il n'existe pas d'étude française équivalente.", 'pb_psmag_2018', '2018', 'États-Unis', "Il ne faut pas surinterpréter un chiffre précis : la prudence vaut dans les deux sens.", 'debat'),
  fait("En 2023, 85 % des victimes de violences sexuelles hors cadre familial enregistrées sont des femmes et 96 % des mis en cause sont des hommes.", 'pb_ssmsi_ir33_2024', '2023', 'France', "Ces violences restent massivement commises par des hommes sur des femmes.", 'etabli', '85 %'),
 ],
 court="Faux : les études estiment les fausses accusations entre 2 et 10 % des faits signalés, alors que seules 2 % des victimes de violences sexuelles portent plainte. Le problème massif, ce sont les violences jamais dénoncées.",
 moyen="Les fausses accusations existent, et elles détruisent des vies. Mais les études les plus citées les situent entre 2 et 10 % des agressions sexuelles signalées. Et en France, seules 2 % des victimes de violences sexuelles hors cadre familial portent plainte : l'immense majorité des violences ne donne lieu à aucune accusation.\n\nLe fait que 83 % des affaires ne soient pas poursuivies ne prouve pas qu'elles sont fausses : le motif principal est le manque de preuves. Depuis 2017, la hausse des plaintes traduit surtout une libération de la parole, avec davantage de faits anciens déclarés.",
 detaille="Depuis l'affaire Weinstein, le nombre de victimes de violences sexuelles enregistrées augmente chaque année. Le service statistique du ministère de l'Intérieur l'explique par la libération de la parole et l'amélioration de l'accueil des victimes : la part des faits commis plus de cinq ans avant la plainte est passée de 13 % en 2018 à 19 % en 2023. Malgré cela, seules 2 % des victimes de violences sexuelles hors cadre familial portent plainte.\n\nCombien d'accusations sont fausses ? Il n'existe pas de mesure française. Une étude américaine de 2010 trouve 5,9 % de fausses allégations sur dix ans dans une université et situe la fourchette entre 2 et 10 %. Ces chiffres sont imparfaits : les définitions varient et une plainte « non fondée » n'est pas forcément mensongère. Il faut donc rester prudent, mais aucun travail sérieux ne montre que les fausses accusations seraient « fréquentes ».\n\nCôté justice, 83 % des affaires de violences sexuelles n'ont pas été poursuivies entre 2012 et 2022, et la part des viols non poursuivis a augmenté. L'Institut des politiques publiques rappelle que cela ne signifie pas que l'infraction n'a pas eu lieu : le plus souvent, les preuves manquent. La présomption d'innocence est essentielle ; elle n'oblige pas à présumer que les victimes mentent.",
 empathie="On peut avoir peur qu'un homme proche soit accusé à tort, ou connaître quelqu'un à qui c'est arrivé. Cette peur est humaine, et une fausse accusation est une injustice grave.",
 legitimes=["Les fausses accusations existent et peuvent briser une vie.", "La présomption d'innocence doit s'appliquer, y compris dans les médias et sur les réseaux sociaux.", "Les chiffres sur les fausses allégations sont fragiles et viennent surtout de l'étranger."],
 contre=[
  ("Si la plupart des plaintes sont classées, c'est bien qu'elles sont fausses.", "Non : le motif principal est l'infraction « insuffisamment caractérisée », faute de preuves. L'IPP précise que cela ne signifie pas que les faits n'ont pas eu lieu."),
  ("Depuis MeToo, il suffit d'accuser pour détruire quelqu'un.", "Seules 2 % des victimes portent plainte, et plus de huit affaires sur dix ne sont pas poursuivies : la justice ne condamne pas sur une simple parole."),
 ],
 questions=["À ton avis, sur cent femmes victimes de violences sexuelles, combien portent plainte ?", "Qu'est-ce qui aiderait à la fois les victimes et les personnes accusées à tort : moins d'enquêtes, ou des enquêtes mieux faites ?"],
 limites=["Aucune étude française ne mesure la part des fausses accusations ; les chiffres de 2 à 10 % viennent d'études américaines anciennes.", "La note IPP existe en plusieurs versions : la version anglaise donne 86 % de classements pour les violences sexuelles et une part de viols non poursuivis passant de 82 % à 94 % jusqu'en 2020 ; la fiche cite la version française d'avril 2024.", "Le taux de plainte de 2 % vient de l'enquête de victimation 2022 et porte sur les violences hors cadre familial.", "Aucune donnée sur les condamnations pour dénonciation calomnieuse n'a été consultée."],
 publics={'convaincus': "Les fausses accusations existent, personne ne le nie. Mais les études les situent entre 2 et 10 % des faits signalés, alors que seules 2 % des victimes portent plainte. Si on veut vraiment protéger les innocents, il faut des enquêtes sérieuses, pas décourager les victimes de parler.",
  'indecis': "C'est légitime de tenir à la présomption d'innocence. Les chiffres disponibles montrent pourtant que le problème principal, ce sont les violences jamais dénoncées et les plaintes qui n'aboutissent pas faute de preuves. Une plainte classée sans suite n'est pas une plainte mensongère."},
 a_actualiser='2027-03-31', raison="Nouveau bilan annuel du SSMSI sur les violences sexuelles et éventuelles nouvelles études françaises.",
))

# 4 ── Les femmes n'osent plus sortir le soir à cause des migrants ──────────
PB_INSEE_FPS_2024 = ('pb_insee_fps_2024', src('Insécurité, victimation (France, portrait social, édition 2024)', 'Insee (Insee Références), d\'après l\'enquête Vécu et ressenti en matière de sécurité du SSMSI', '21 novembre 2024',
  'https://www.insee.fr/fr/statistiques/8242369',
  "En 2022, en France métropolitaine, chez les 18-74 ans : 21 % des femmes et 15 % des hommes se sentent en insécurité dans leur quartier ou leur village ; « il arrive à 27 % des femmes de renoncer à sortir seules de chez elles, contre 7 % des hommes seulement » ; 15 % des femmes et 10 % des hommes se sentent en insécurité à leur domicile. En 2021, 247 000 personnes ont subi des violences sexuelles physiques ; les femmes représentent 88 % de ces victimes et 76 % des victimes de violences conjugales.",
  "Statistique publique de référence.", 'primaire'))
PB_INED_VIRAGE_PS550 = ('pb_ined_virage_ps550', src('Les violences dans les espaces publics touchent surtout les jeunes femmes des grandes villes (Population & Sociétés n° 550)', 'INED (Amandine Lebugle et l\'équipe Virage), document hébergé par le Centre Hubertine Auclert', 'décembre 2017',
  'https://www.centre-hubertine-auclert.fr/sites/default/files/medias/egalitheque/documents/550-populationsocietesdecembre2017violences-1fr.pdf',
  "Enquête Virage 2015 auprès de 27 268 personnes de 20 à 69 ans. Viols et tentatives de viol : 0,9 % des femmes dans les espaces publics, 1,6 % dans la famille, 1,4 % dans le couple. Dans les espaces publics, les auteurs sont des inconnus dans 88 % des cas pour les femmes. Sur douze mois, 25 % des femmes et 14 % des hommes ont subi au moins une forme de violence dans l'espace public ; 15 % des femmes ont subi uniquement de la drague importune et 5 % du harcèlement ou des agressions sexuelles.",
  "Institut public de recherche ; enquête de référence sur les violences de genre.", 'etude'))
PB_SSMSI_IR33_FEMMES = ('pb_ssmsi_ir33_femmes', src('Les violences sexuelles hors cadre familial enregistrées par les services de sécurité en 2023 (Interstats Info Rapide n° 33)', 'SSMSI (ministère de l\'Intérieur)', 'mars 2024',
  'https://interieur.gouv.fr/content/download/136125/1077745/file/IR33-Violences sexuelles hors cadre familial.pdf',
  "En 2023, 54 586 personnes mises en cause pour violences sexuelles hors cadre familial : 96 % d'hommes, 87 % de nationalité française, 28 % de mineurs. 85 % des victimes sont des femmes. Taux de victimes enregistrées chez les femmes de 15 à 64 ans : 2,1 ‰ en moyenne nationale, de 1,2 ‰ (Corse-du-Sud) à 4,4 ‰ (Paris) ; 1,1 ‰ dans les communes rurales.",
  "Service statistique ministériel de la sécurité intérieure.", 'primaire'))
PB_SSMSI_IR42_2024 = ('pb_ssmsi_ir42_2024', src('Les vols et violences enregistrés dans les réseaux de transports en commun en 2023 (Interstats Info Rapide n° 42)', 'SSMSI (ministère de l\'Intérieur)', 'septembre 2024',
  'https://www.banquedesterritoires.fr/sites/default/files/2024-09/IR%2042%20-%20Les%20vols%20et%20violences%20dans%20les%20r%C3%A9seaux%20de%20transports%20en%20commun%20en%202023pdf%20%281%29.pdf',
  "3 174 victimes de violences sexuelles enregistrées dans les transports en commun en 2023 (+3 % par rapport à 2022). Pour l'ensemble des vols et violences élucidés dans les transports en commun : 87 % des mis en cause sont des hommes, 24 % des mineurs, et 52 % sont enregistrés comme étrangers.",
  "Service statistique ministériel ; document hébergé par la Banque des Territoires.", 'primaire'))

FICHES.append(fiche(
 id='femmes-sortir-soir-migrants', affirmation="Les femmes n'osent plus sortir le soir à cause des migrants.", volet='securite', sous_theme='Sécurité du quotidien',
 mots_cles=['femmes peur sortir le soir', 'femmes insecurite migrants', 'migrants agressent les femmes', 'harcelement de rue migrants', 'femmes renoncent a sortir', 'insecurite femmes rue', 'peur la nuit femmes', 'agressions sexuelles etrangers', 'harcelement transports', 'on ne peut plus sortir seule'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. La peur des femmes est réelle : 27 % d'entre elles renoncent parfois à sortir seules, contre 7 % des hommes. Mais l'enquête qui le mesure n'en attribue pas la cause aux migrants. Les violences sexuelles les plus graves ont lieu surtout dans la famille et le couple, et 87 % des personnes mises en cause pour violences sexuelles hors famille sont françaises. Les étrangers sont en revanche surreprésentés parmi les mis en cause pour vols et violences dans les transports.",
 contexte="Après certaines agressions médiatisées, des responsables politiques affirment que l'immigration chasse les femmes de l'espace public.",
 explication="Il faut séparer trois questions : le sentiment d'insécurité des femmes, les lieux réels des violences et le profil des auteurs, en s'appuyant sur les enquêtes de victimation et les statistiques policières.",
 sources=[PB_INSEE_FPS_2024, PB_INED_VIRAGE_PS550, PB_SSMSI_IR33_FEMMES, PB_SSMSI_IR42_2024],
 faits=[
  fait("En 2022, 27 % des femmes de 18 à 74 ans renoncent parfois à sortir seules de chez elles, contre 7 % des hommes ; 21 % des femmes se sentent en insécurité dans leur quartier, contre 15 % des hommes.", 'pb_insee_fps_2024', '2022', 'France métropolitaine', "Fait défavorable : le sentiment d'insécurité des femmes est réel, élevé et bien plus fort que celui des hommes.", 'etabli', '27 %'),
  fait("Selon l'enquête Virage, 0,9 % des femmes ont subi un viol ou une tentative dans les espaces publics, contre 1,6 % dans la famille et 1,4 % dans le couple ; dans l'espace public, les auteurs sont des inconnus dans 88 % des cas.", 'pb_ined_virage_ps550', '2015', 'France métropolitaine', "Les violences les plus graves sont surtout commises par des proches, même si la rue reste un lieu de danger.", 'etabli', '1,6 %'),
  fait("Sur douze mois, 25 % des femmes ont subi au moins une forme de violence dans l'espace public, le plus souvent de la drague importune ou du harcèlement.", 'pb_ined_virage_ps550', '2015', 'France métropolitaine', "Le harcèlement de rue est massif : il explique une grande part de la peur des femmes.", 'etabli', '25 %'),
  fait("En 2023, 96 % des personnes mises en cause pour violences sexuelles hors cadre familial sont des hommes et 87 % sont de nationalité française.", 'pb_ssmsi_ir33_femmes', '2023', 'France', "Le problème, ce sont surtout des hommes, très majoritairement français.", 'etabli', '87 %'),
  fait("Fait défavorable : dans les transports en commun, 52 % des mis en cause pour l'ensemble des vols et violences élucidés en 2023 sont enregistrés comme étrangers ; 3 174 victimes de violences sexuelles y ont été enregistrées.", 'pb_ssmsi_ir42_2024', '2023', 'France', "Pour certains faits et lieux, les étrangers sont surreprésentés parmi les mis en cause ; ce chiffre ne porte pas sur les seules violences sexuelles.", 'etabli', '52 %'),
 ],
 court="La peur des femmes est réelle : 27 % renoncent parfois à sortir seules. Mais 87 % des mis en cause pour violences sexuelles hors famille sont français, et les violences les plus graves ont lieu surtout dans la famille et le couple.",
 moyen="Les femmes ont bien plus peur que les hommes : en 2022, 27 % d'entre elles renoncent parfois à sortir seules, contre 7 % des hommes. Cette peur s'explique notamment par le harcèlement de rue : un quart des femmes subit chaque année une forme de violence dans l'espace public.\n\nMais les auteurs ne sont pas d'abord des migrants. En 2023, 87 % des mis en cause pour violences sexuelles hors cadre familial sont français, et les viols ont lieu plus souvent dans la famille ou le couple que dans la rue. Dans les transports, les étrangers sont surreprésentés parmi les mis en cause pour vols et violences : un fait réel, qui ne justifie pas de désigner tout un groupe.",
 detaille="Le sentiment d'insécurité des femmes est un fait solide. Selon l'enquête de victimation du ministère de l'Intérieur reprise par l'Insee, 27 % des femmes de 18 à 74 ans renoncent parfois à sortir seules, contre 7 % des hommes, et 21 % se sentent en insécurité dans leur quartier. L'enquête Virage de l'INED montre qu'un quart des femmes subit chaque année au moins une violence dans l'espace public, le plus souvent de la drague importune ou du harcèlement.\n\nQui sont les auteurs ? Pour les violences sexuelles hors cadre familial enregistrées en 2023, 96 % des mis en cause sont des hommes et 87 % sont français. Et les violences sexuelles les plus graves se produisent surtout dans la famille et le couple : 1,6 % des femmes ont subi un viol ou une tentative dans la famille, 1,4 % dans le couple, 0,9 % dans l'espace public. Le danger principal n'est donc pas l'inconnu étranger, même si, dans la rue, les agresseurs sont le plus souvent des inconnus.\n\nIl faut être honnête : dans les transports en commun, 52 % des mis en cause pour vols et violences élucidés sont enregistrés comme étrangers. Ce chiffre global ne dit rien des seules violences sexuelles et reflète aussi la précarité, l'âge et les contrôles. Pour que les femmes reprennent la rue, il faut de l'éclairage, du personnel dans les gares, des transports de nuit, l'éducation des garçons et la lutte contre le harcèlement, quel que soit l'agresseur.",
 empathie="Rentrer seule le soir avec les clés serrées dans la main, beaucoup de femmes connaissent. Cette peur est réelle et légitime ; elle mérite des réponses sérieuses, pas un bouc émissaire.",
 legitimes=["Le sentiment d'insécurité des femmes est réel et bien plus élevé que celui des hommes.", "Dans l'espace public, les agresseurs sont le plus souvent des inconnus.", "Les étrangers sont surreprésentés parmi les mis en cause pour vols et violences dans les transports."],
 contre=[
  ("Avant, on pouvait sortir tranquille.", "Aucune source lue ne mesure l'évolution de la peur des femmes depuis l'arrivée de migrants ; le harcèlement de rue et les violences masculines sont anciens."),
  ("Les chiffres montrent que les étrangers sont surreprésentés.", "Dans les transports, pour les vols et violences en général, oui. Mais pour les violences sexuelles hors famille, 87 % des mis en cause sont français."),
 ],
 questions=["D'après toi, où une femme a-t-elle le plus de risques de subir un viol : dans la rue, ou chez elle ?", "Qu'est-ce qui rassurerait concrètement une femme qui rentre le soir : plus d'éclairage et de personnel, ou un discours sur les migrants ?"],
 limites=["L'enquête Virage date de 2015.", "Le chiffre de 52 % d'étrangers porte sur l'ensemble des vols et violences élucidés dans les transports, pas sur les seules violences sexuelles ; les mis en cause ne sont pas des condamnés.", "Aucune source lue ne relie directement le sentiment d'insécurité des femmes à la présence de migrants, ni n'en mesure l'évolution récente par sexe.", "Les statistiques policières distinguent la nationalité, pas le statut de migrant ou de demandeur d'asile."],
 publics={'convaincus': "La peur des femmes est réelle, personne ne le conteste : 27 % renoncent parfois à sortir seules. Mais 87 % des mis en cause pour violences sexuelles hors famille sont français, et les viols ont lieu surtout dans la famille et le couple. Si on ne parle que des migrants, on laisse tranquilles la majorité des agresseurs.",
  'indecis': "Ta peur, ou celle de tes proches, est légitime. Les chiffres montrent qu'elle vient surtout du harcèlement de rue, très répandu, et que la plupart des auteurs de violences sexuelles sont des hommes français. Les étrangers sont surreprésentés dans certains faits, comme dans les transports : la réponse, ce sont plus de présence humaine et de prévention, pour toutes les femmes."},
 a_actualiser='2027-03-31', raison="Nouvelle édition de l'enquête Vécu et ressenti en matière de sécurité et nouveaux bilans SSMSI.",
))

# 5 ── Burkini dans les piscines ─────────────────────────────────────────────
PB_CE_GRENOBLE_2022 = ('pb_ce_grenoble_2022', src("Burkini dans les piscines de Grenoble : le juge des référés du Conseil d'État confirme la suspension (ordonnance n° 464648)", "Conseil d'État (communiqué de presse)", '21 juin 2022',
  'https://www.conseil-etat.fr/content/download/175427/document/Communiqu%C3%A9%20de%20presse%20-%20Grenoble%20-%20web.pdf',
  "Le Conseil d'État confirme la suspension, prononcée le 25 mai 2022 par le tribunal administratif de Grenoble, du règlement des piscines qui autorisait les tenues de bain amples. Il juge qu'il s'agit d'une « dérogation très ciblée » destinée à satisfaire une revendication religieuse, qui affecte le bon fonctionnement du service public et l'égalité de traitement des usagers. Il rappelle que le gestionnaire d'un service public peut adapter ses règles pour tenir compte des convictions religieuses des usagers, sans qu'ils y aient droit, et que les règles de tenues ajustées au corps ont été fixées pour des raisons d'hygiène et de sécurité.",
  "Juridiction administrative suprême ; communiqué officiel.", 'primaire'))
PB_CE_VILLENEUVE_2016 = ('pb_ce_villeneuve_2016', src("Ordonnance du 26 août 2016, Ligue des droits de l'homme et autres (n° 402742)", "Conseil d'État", '26 août 2016',
  'https://conseil-etat.fr/fr/arianeweb/CE/decision/2016-08-26/402742',
  "Le juge suspend l'arrêté anti-burkini de Villeneuve-Loubet sur les plages : « Il ne résulte pas de l'instruction que des risques de trouble à l'ordre public aient résulté » de la tenue de certaines personnes ; « l'émotion et les inquiétudes résultant des attentats terroristes » « ne sauraient suffire à justifier légalement la mesure d'interdiction contestée ». « L'arrêté litigieux a ainsi porté une atteinte grave et manifestement illégale aux libertés fondamentales » : liberté d'aller et venir, liberté de conscience, liberté personnelle.",
  "Décision de justice (Conseil d'État, juge des référés).", 'primaire'))
PB_FP_NEUTRALITE = ('pb_fp_neutralite', src('Laïcité et neutralité de la fonction publique', 'Ministère de la Fonction publique (fonction-publique.gouv.fr)', 'mise à jour le 11 avril 2024',
  'https://www.fonction-publique.gouv.fr/etre-agent-public/mes-droits-et-obligations/laicite-et-neutralite-de-la-fonction-publique',
  "L'obligation de neutralité s'applique aux agents publics (titulaires, contractuels, stagiaires, élèves) : dans l'exercice de leurs fonctions, ils ne doivent pas « manifester leurs convictions qu'elles soient religieuses, philosophiques ou politiques ». La neutralité protège les usagers « par le traitement égalitaire de toutes les personnes ». Références : articles L. 121-2 et L. 121-4 du code général de la fonction publique, article 1er de la Constitution, loi du 9 décembre 1905.",
  "Site officiel du ministère.", 'primaire'))
PB_CDJ_VALLAR_2022 = ('pb_cdj_vallar_2022', src("Déféré-laïcité et burkini : le Conseil d'État rappelle la primauté de la neutralité du service public", 'Le Club des juristes (Christian Vallar, professeur de droit public, Université Côte d\'Azur)', '27 juin 2022',
  'https://www.leclubdesjuristes.com/justice/defere-laicite-et-burkini-le-conseil-detat-rappelle-la-primaute-de-la-neutralite-du-service-public-par-christian-vallar-professeur-de-droit-public-a-luniversite-cote-d-626/',
  "Les usagers du service public peuvent exprimer leur appartenance religieuse, mais la croyance ne permet pas de s'affranchir des règles communes ; laïcité et neutralité ne s'opposent pas à la prise en compte des convictions, à condition de ne pas créer de rupture d'égalité. L'affaire de Grenoble est la première application du déféré-laïcité créé par la loi du 24 août 2021. Les plages, où le Conseil d'État avait suspendu l'arrêté de Villeneuve-Loubet en 2016, ne sont pas un service public.",
  "Analyse d'un professeur de droit public dans un think tank juridique reconnu.", 'secondaire'))
