FICHES.append(fiche(
 id='jules-ferry-gauche-colonialisme', affirmation="Jules Ferry était de gauche et colonialiste, la gauche a toujours été raciste.", volet='international', sous_theme='Colonisation et décolonisation',
 mots_cles=['jules ferry', 'ferry races inferieures', 'gauche coloniale', 'gauche raciste', 'gauche colonialiste', 'guy mollet algerie', 'clemenceau colonisation', 'races superieures', 'socialistes guerre d algerie', 'communistes guerre du rif'],
 verdict='trompeur', fiabilite='etabli', stabilite='historique',
 resume="En partie vrai, mais la conclusion est fausse. Jules Ferry, républicain de la gauche de son époque, a défendu en 1885 le « droit » des « races supérieures » sur les « races inférieures ». Et une grande partie de la gauche a soutenu la colonisation, jusqu'au socialiste Guy Mollet qui a fait voter les pouvoirs spéciaux en Algérie en 1956, communistes compris. Mais c'est un radical, Clemenceau, qui a répondu à Ferry en dénonçant « la primauté de la force sur le droit », pendant qu'une partie de la droite monarchiste s'opposait aux colonies pour des raisons de revanche. Et les premières grandes luttes anticoloniales en France, comme la grève contre la guerre du Rif en 1925, sont venues du mouvement ouvrier. Le colonialisme a traversé tous les camps ; l'anticolonialisme est surtout né à gauche.",
 contexte="Cette phrase sert à retourner l'accusation de racisme contre la gauche. Elle s'appuie sur des faits réels, Ferry et la guerre d'Algérie, pour en tirer une conclusion générale.",
 explication="Il faut lire ce qu'a dit Ferry, qui lui a répondu, qui soutenait ou combattait la colonisation à chaque époque, et pourquoi.",
 sources=[PC_AN_CLEMENCEAU_1885, PC_HCP_FERRY_1885, PC_AN_FERRY_BIO, PC_HERODOTE_COLONISATION, PC_MEE_PCF_2021, PC_ARMEES_APPELES_2026, PC_HERODOTE_MOLLET_1956],
 faits=[
  fait("Le 28 juillet 1885, Jules Ferry déclare à la Chambre : « Il faut dire ouvertement qu'en effet les races supérieures ont un droit vis-à-vis des races inférieures », provoquant des « rumeurs » à l'extrême gauche.", 'pc_hcp_ferry_1885', '1885', 'France', "Fait défavorable : un républicain de la gauche de l'époque a bien justifié la colonisation par la hiérarchie des « races ».", 'etabli'),
  fait("Le radical Georges Clemenceau lui répond le 31 juillet 1885 : « Races supérieures ? races inférieures, c'est bientôt dit ! », et dénonce « la proclamation de la primauté de la force sur le droit ».", 'pc_an_clemenceau_1885', '1885', 'France', "Dès 1885, la critique la plus célèbre de Ferry vient de la gauche.", 'etabli'),
  fait("Dans les années 1880, les royalistes et la droite nationaliste s'opposaient aussi à l'expansion coloniale, mais pour privilégier la revanche contre l'Allemagne ; le soutien de la droite aux colonies grandit après la Première Guerre mondiale.", 'pc_herodote_colonisation', '1880-1920', 'France', "L'opposition de droite aux colonies n'était pas antiraciste : le clivage ne recoupe pas gauche et droite.", 'interpretation'),
  fait("En 1925, le PCF mène contre la guerre du Rif une campagne et une grève qui mobilisent « des centaines de milliers de travailleurs », réprimées par des perquisitions, des saisies de journaux et des emprisonnements.", 'pc_mee_pcf_2021', '1925', 'France et Maroc', "Le mouvement ouvrier a porté les premières grandes mobilisations anticoloniales.", 'etabli'),
  fait("Le 12 mars 1956, l'Assemblée vote les pouvoirs spéciaux proposés par le président du Conseil Guy Mollet ; le service est porté à 27 mois et 400 000 à 470 000 hommes sont stationnés en Algérie entre 1956 et 1962.", 'pc_armees_appeles_2026', '1956-1962', 'France et Algérie', "Fait défavorable : la gauche au pouvoir a intensifié la guerre d'Algérie.", 'etabli', '27 mois'),
  fait("Guy Mollet, arrivé au pouvoir après la victoire du Front républicain, avait dénoncé dans Le Populaire, « l'organe officiel de la SFIO », une « guerre imbécile et sans issue » ; en mars 1956, les députés, « communistes compris », votent les pouvoirs spéciaux.", 'pc_herodote_mollet_1956', '1956', 'France', "Fait défavorable : socialistes et communistes ont voté ensemble ce tournant de la guerre.", 'etabli'),
 ],
 court="Ferry a bien parlé des « races supérieures », et Guy Mollet, socialiste, a intensifié la guerre d'Algérie. Mais c'est un homme de gauche, Clemenceau, qui a répondu à Ferry, et les premières luttes anticoloniales sont venues du mouvement ouvrier. Le colonialisme a traversé tous les camps.",
 moyen="Le 28 juillet 1885, Jules Ferry affirme que « les races supérieures ont un droit vis-à-vis des races inférieures ». Trois jours plus tard, le radical Clemenceau lui répond : « Races supérieures ? races inférieures, c'est bientôt dit ! » La droite monarchiste s'opposait aussi aux colonies, mais pour préparer la revanche contre l'Allemagne.\n\nIl faut le reconnaître : une grande partie de la gauche a soutenu la colonisation. En 1956, le socialiste Guy Mollet obtient les pouvoirs spéciaux en Algérie, avec les voix communistes. Mais c'est aussi la gauche ouvrière qui a lancé les premières grandes luttes anticoloniales, comme la grève contre la guerre du Rif en 1925. Dire que « la gauche a toujours été raciste » efface ces combats.",
 detaille="La citation est authentique. Le 28 juillet 1885, à la Chambre, Jules Ferry déclare : « Il faut dire ouvertement qu'en effet les races supérieures ont un droit vis-à-vis des races inférieures », et parle d'un « devoir de civiliser ». Ferry était un républicain, de la gauche de son temps, fondateur de l'école gratuite, laïque et obligatoire. Son successeur, le radical Henri Brisson, a poursuivi la même politique coloniale.\n\nMais le débat de 1885 ne se résume pas à « la gauche colonialiste ». C'est le radical Georges Clemenceau qui répond à Ferry, le 31 juillet : « Races supérieures ? races inférieures, c'est bientôt dit ! », en rappelant les civilisations indienne et chinoise et en dénonçant « la primauté de la force sur le droit ». À droite, les royalistes et les nationalistes s'opposaient aussi aux colonies, mais pour garder les forces contre l'Allemagne, pas par antiracisme. En 1925, le jeune PCF organise contre la guerre du Rif une grève suivie par des centaines de milliers de travailleurs, réprimée par l'État.\n\nIl faut regarder en face la part sombre de l'histoire de la gauche. Jaurès voulait encadrer la colonisation plutôt que la supprimer, Léon Blum l'a défendue, et en 1956 le socialiste Guy Mollet a fait voter les pouvoirs spéciaux en Algérie, communistes compris, avant l'envoi massif du contingent. Le colonialisme a traversé tous les partis ; l'anticolonialisme, lui, est né pour l'essentiel dans le mouvement ouvrier et la gauche. Une gauche fidèle à ses principes universalistes est celle qui reconnaît ces erreurs et défend l'égalité de tous les êtres humains.",
 empathie="On a parfois l'impression que la gauche donne des leçons d'antiracisme sans balayer devant sa porte. Ce reproche mérite une réponse honnête, faits à l'appui.",
 legitimes=["Jules Ferry, figure de la gauche républicaine, a bien justifié la colonisation par la supériorité de certaines « races ».", "Le socialiste Guy Mollet a intensifié la guerre d'Algérie en 1956, avec le vote des communistes."],
 contre=[
  ("La droite n'a jamais été colonialiste, c'était un projet de gauche.", "La droite monarchiste s'y opposait d'abord pour la revanche contre l'Allemagne, mais son soutien aux colonies grandit après la Première Guerre mondiale ; le colonialisme a traversé tous les camps."),
  ("Les communistes aussi ont soutenu la guerre d'Algérie.", "C'est vrai pour le vote des pouvoirs spéciaux en 1956, et c'est une faute ; mais le même parti avait mené en 1925 une grève de masse contre la guerre du Rif."),
  ("La gauche n'a pas de leçon à donner.", "Reconnaître ses erreurs ne disqualifie pas l'antiracisme ; c'est justement au nom de l'égalité qu'on peut juger Ferry et Mollet."),
 ],
 questions=["Savais-tu que c'est Clemenceau, un homme de gauche, qui a répondu à Ferry sur les « races supérieures » ?", "Si la colonisation a été soutenue à droite comme à gauche, qu'est-ce qui permet aujourd'hui de la condamner, sinon l'idée d'égalité ?"],
 limites=["La citation de Ferry a été lue dans des extraits reproduits par des sites associatifs et de vulgarisation, pas dans le Journal officiel ; la date de la réponse de Clemenceau varie (30 ou 31 juillet 1885) selon les sources, l'Assemblée retient le 31.", "Le nombre de voix sur les pouvoirs spéciaux de 1956 n'a pas été vérifié dans une source lue.", "Herodote.net et Middle East Eye sont des sources secondaires ; les travaux d'Alain Ruscio n'ont pas été lus directement.", "Le jugement d'Herodote selon lequel socialistes et communistes ne condamnèrent la colonisation qu'à la fin des années 1950 est discutable au vu de la campagne contre la guerre du Rif."],
 publics={'convaincus': "Oui, Ferry a parlé des « races supérieures », et Guy Mollet a intensifié la guerre d'Algérie : ce sont des faits. Mais c'est Clemenceau, un homme de gauche, qui a répondu à Ferry, et la droite monarchiste qui s'opposait aux colonies ne le faisait pas par antiracisme. Le colonialisme a traversé tous les camps ; l'anticolonialisme est surtout né dans le mouvement ouvrier.",
  'indecis': "C'est juste de rappeler que la gauche a eu sa part dans la colonisation, de Ferry à Mollet. Mais elle a aussi porté les premières luttes anticoloniales, de Clemenceau en 1885 à la grève contre la guerre du Rif en 1925. L'histoire est plus mêlée qu'un slogan."},
 a_actualiser='2028-12-31', raison="Fiche historique ; à revoir si une source primaire (Journal officiel de 1885, scrutin du 12 mars 1956) devient consultable.",
))

