PD_MONEYVOX_REFUS_2025 = ('pd_moneyvox_refus_2025', src('Linky : une très mauvaise nouvelle pour les opposants aux compteurs communicants', 'MoneyVox', '30 avril 2025',
  'https://www.moneyvox.fr/energie/actualites/103183/linky-une-tres-mauvaise-nouvelle-pour-les-opposants-aux-compteurs-communicants',
  "La Cour de cassation a confirmé que « les usagers ne peuvent s'opposer à l'installation d'un compteur Linky sur leur propriété ». Un surcoût s'applique aux foyers sans Linky à partir de l'été 2025 : « 6,48 euros tous les deux mois » s'ils transmettent leurs index, 63,72 € par an sinon. Selon Enedis, plus de 37,4 millions de compteurs installés, « soit 95% des foyers équipés ».",
  "Site d'information sur la consommation et l'argent.", 'secondaire'))

FICHES.append(fiche(
 id='linky-dangereux-espionnage', affirmation="Le compteur Linky est dangereux et sert à nous espionner.", volet='ecologie', sous_theme='Prix de l’énergie',
 mots_cles=['linky dangereux', 'linky ondes', 'linky espionnage', 'compteur linky sante', 'linky donnees personnelles', 'linky cancer', 'refuser linky', 'linky electrosensible', 'compteur communicant', 'linky courbe de charge', 'linky surcout'],
 verdict='contredit', fiabilite='etabli',
 resume="Faux pour la santé, à nuancer pour les données. Les mesures officielles montrent un champ très faible, comparable à celui d'un chargeur d'ordinateur, et l'ANSES juge peu probable un effet sanitaire. Côté vie privée, le compteur ne relève par défaut qu'un index par jour ; la courbe détaillée exige l'accord de l'abonné. La CNIL a pourtant sanctionné EDF et Engie en 2020 pour un consentement mal recueilli, corrigé depuis. La vraie critique est ailleurs : la Cour des comptes a jugé en 2018 que ce projet de 5,7 milliards d'euros, payé par les usagers, leur profitait trop peu, et la pose est devenue quasi obligatoire.",
 contexte="Le déploiement du compteur Linky, à partir de 2015, a suscité une forte opposition : craintes pour la santé, peur de la surveillance, poses jugées imposées. Depuis 2025, les foyers qui le refusent paient un surcoût.",
 explication="Il faut séparer trois questions : l'exposition aux ondes (mesures ANFR, avis ANSES), l'usage des données (règles de consentement, contrôles de la CNIL), et le coût et le bénéfice pour les usagers (Cour des comptes).",
 sources=[PD_AN_QE9477_2018, PD_INC_LINKY_DONNEES, PD_CNIL_MED_2020, PD_AFP_CNIL_2021, PD_LOCALTIS_CDC_2018, PD_MONEYVOX_REFUS_2025],
 faits=[
  fait("Selon l'ANSES (2017), les niveaux d'exposition des compteurs communicants sont « très faibles par rapport aux valeurs réglementaires » et il est « peu probable » qu'ils aient des effets sanitaires à court ou long terme ; à 30 cm, le champ magnétique est comparable à celui d'un chargeur d'ordinateur.", 'pd_an_qe9477_2018', '2016-2018', 'France', "Le risque sanitaire n'est pas démontré, et l'exposition est minime.", 'etabli'),
  fait("Par défaut, le compteur transmet un index par jour, la nuit ; la courbe de charge (toutes les 30 minutes) n'est transmise qu'avec l'autorisation explicite de l'abonné, et un tiers n'y accède qu'avec un consentement « éclairé et écrit ».", 'pd_inc_linky_donnees', '2017-2021', 'France', "Le suivi fin de la consommation n'est pas automatique ; l'abonné garde la main.", 'etabli'),
  fait("En février 2020, la CNIL a mis en demeure EDF et Engie pour un consentement recueilli par une case unique couvrant deux usages distincts, et pour une conservation excessive des données ; les mises en demeure ont été closes en 2021 après correction.", 'pd_cnil_med_2020', '2020-2021', 'France', "Fait défavorable : les inquiétudes sur les données n'étaient pas toutes infondées, mais le régulateur a agi.", 'etabli'),
  fait("Selon la Cour des comptes (2018), Linky coûte près de 5,7 milliards d'euros, environ 130 € par compteur, « in fine payé par le consommateur » ; la rémunération d'Enedis est jugée « généreuse » et les outils de maîtrise de la consommation sont « très insuffisants ».", 'pd_localtis_cdc_2018', '2018', 'France', "Fait défavorable : la vraie faiblesse de Linky est son bénéfice limité pour les usagers qui le paient.", 'etabli', '5,7 milliards d’euros'),
  fait("La Cour de cassation a jugé que les usagers ne peuvent s'opposer à l'installation ; depuis l'été 2025, les foyers sans Linky paient un surcoût, de 6,48 € tous les deux mois s'ils transmettent leurs index. 95 % des foyers sont équipés selon Enedis.", 'pd_moneyvox_refus_2025', '2025', 'France', "Fait défavorable : la pose est devenue quasi obligatoire, ce qui nourrit le sentiment d'imposition.", 'etabli', '95 %'),
 ],
 court="Les mesures officielles montrent que Linky émet très peu d'ondes, comme un chargeur d'ordinateur. Il ne transmet par défaut qu'une consommation par jour, et le détail exige ton accord. Le vrai problème, c'est qu'il a coûté 5,7 milliards aux usagers pour un bénéfice jugé trop faible par la Cour des comptes.",
 moyen="Les mesures de l'ANFR et l'avis de l'ANSES sont clairs : l'exposition est très faible, comparable à celle d'un chargeur d'ordinateur, et un effet sur la santé est jugé peu probable. Côté données, le compteur envoie un index par jour ; la courbe à la demi-heure n'est transmise qu'avec l'accord de l'abonné.\n\nIl y a eu des abus : la CNIL a mis en demeure EDF et Engie en 2020 pour un consentement mal recueilli, corrigé depuis. Et la Cour des comptes a jugé en 2018 que ce projet de 5,7 milliards d'euros, payé par les usagers, servait surtout Enedis. Depuis 2025, refuser Linky coûte un surcoût.",
 detaille="Sur la santé, les faits sont rassurants. L'INERIS, le CSTB et l'ANFR ont mesuré l'exposition en laboratoire et dans des logements : le champ est nettement inférieur aux valeurs réglementaires, et à 30 cm, il est comparable à celui d'un chargeur d'ordinateur. L'ANSES a conclu en 2017 qu'il est « peu probable » que ces ondes aient des effets sanitaires. Toute personne peut demander gratuitement une mesure à l'ANFR.\n\nSur l'espionnage, la réalité est plus nuancée. Par défaut, le compteur transmet un index par jour, la nuit. La courbe de charge, qui pourrait révéler des habitudes de vie comme le craignait la CNIL, n'est transmise qu'avec un accord explicite. Mais en 2020, la CNIL a mis en demeure EDF et Engie, qui recueillaient ce consentement par une seule case couvrant plusieurs usages et gardaient trop longtemps les données. Les deux entreprises ont corrigé en 2021. La vigilance citoyenne et le régulateur ont donc servi à quelque chose.\n\nLa critique la plus solide vient de la Cour des comptes. En 2018, elle relevait que Linky coûtait près de 5,7 milliards d'euros, payés au final par les consommateurs, que la rémunération d'Enedis était « généreuse » et que les usagers en tiraient trop peu de bénéfices. Depuis, la Cour de cassation a jugé qu'on ne pouvait pas s'opposer à la pose, et les foyers sans Linky paient un surcoût depuis 2025. Le vrai débat porte sur un service public de l'énergie au service des usagers, pas sur des ondes dangereuses.",
 empathie="Voir un appareil posé chez soi sans vraiment avoir le choix, avec des données qui partent on ne sait où, peut donner un sentiment de dépossession. Cette méfiance mérite des réponses précises.",
 legitimes=["La CNIL a réellement sanctionné EDF et Engie en 2020 pour un consentement mal recueilli.", "La Cour des comptes a jugé le bénéfice pour les usagers trop faible et la rémunération d'Enedis généreuse.", "La pose est devenue quasi obligatoire, avec un surcoût pour ceux qui refusent."],
 contre=[
  ("Les ondes de Linky donnent des cancers.", "L'ANSES juge peu probable tout effet sanitaire ; à 30 cm, le champ est comparable à celui d'un chargeur d'ordinateur."),
  ("Linky sait quand je suis chez moi et le revend.", "Par défaut, il transmet un index par jour. La courbe détaillée et le partage avec des tiers exigent ton accord, et la CNIL a sanctionné les abus."),
  ("C'est l'État qui m'a imposé ce compteur pour me surveiller.", "La pose est quasi obligatoire, c'est vrai, mais pour des raisons de gestion du réseau et de facturation. La critique sérieuse porte sur le coût payé par les usagers, pas sur l'espionnage."),
 ],
 questions=["Savais-tu que tu peux refuser la transmission de ta courbe de charge détaillée et faire mesurer gratuitement les ondes chez toi ?", "Qui devrait profiter des économies permises par Linky : les usagers qui l'ont payé, ou le gestionnaire du réseau ?"],
 limites=["L'avis de l'ANSES date de 2017 et a été lu à travers une réponse ministérielle ; l'avis original n'a pas été ouvert.", "Le rapport de la Cour des comptes (2018) a été lu via un compte rendu de Localtis ; ses chiffres datent de 2017.", "L'article de MoneyVox ne précise pas la date de l'arrêt de la Cour de cassation.", "La page de l'INC date de 2017, mise à jour en 2021 ; les modalités d'accès aux données ont pu évoluer."],
 publics={'convaincus': "Les mesures officielles sont claires : Linky émet aussi peu d'ondes qu'un chargeur d'ordinateur. Pour les données, la CNIL veille : elle a même sanctionné EDF et Engie en 2020, qui ont dû corriger. Si tu veux une vraie colère, prends celle de la Cour des comptes : 5,7 milliards payés par les usagers, au bénéfice surtout d'Enedis.",
  'indecis': "Ta méfiance est compréhensible. Les ondes sont très faibles selon l'ANSES, et le compteur ne transmet qu'une consommation par jour sans ton accord. Tu peux refuser le suivi détaillé et demander une mesure gratuite des ondes. Les critiques sérieuses portent sur le coût et la pose imposée."},
 a_actualiser='2027-06-30', raison="Évolution du surcoût pour les foyers sans Linky et éventuels nouveaux avis de l'ANSES ou de la CNIL.",
))

