PE_IFRI_HECKER_2018 = ('pe_ifri_hecker_2018', src('137 nuances de terrorisme. Les djihadistes de France face à la justice (Focus stratégique n° 79)', 'Institut français des relations internationales (Ifri), Marc Hecker', 'avril 2018',
  'https://www.jugendundmedien.ch/fileadmin/PDFs/anderes/schwerpunkt_Radikalisierung/hecker_137_nuances_de_terrorisme_2018.pdf',
  "Étude de 137 individus condamnés en France dans des affaires de terrorisme djihadiste (jugements de 2004 à 2017). Sur 130 personnes dont la nationalité est connue : 90 Français, 29 binationaux et 11 étrangers. « Les individus condamnés sont en grande majorité nés en France et ont grandi dans ce pays. » 35 convertis sur 136 (26 %) ; 49 sur 121 (40 %) viennent d'un quartier prioritaire de la politique de la ville ; 61 sur 126 avaient un casier judiciaire vierge.",
  "Étude de référence d'un centre de recherche reconnu, fondée sur les jugements ; copie du PDF de l'Ifri hébergée par un site suisse (la version anglaise sur ifri.org donne les mêmes chiffres).", 'etude'))
PE_CAT_2024 = ('pe_cat_2024', src('Terrorisme islamiste en France : attentats, tentatives et projets d\'attentats (2020-2023)', 'Centre d\'analyse du terrorisme (CAT), Emma Cantelaube et Adam El Difraoui', 'juillet 2024',
  'https://www.cat-int.org/wp-content/uploads/2024/07/CAT_RAPPORT_Terrorisme_islamiste_en_France_attentats_tentatives.pdf',
  "25 incidents recensés de 2020 à 2023 : 8 attentats aboutis, 2 tentatives et 15 projets déjoués, impliquant 39 individus. « Sur les 29 individus dont la nationalité est connue, 13 sont Français (44,8 %). » Les Russes, souvent originaires des républiques du Caucase, représentent 17,2 %. « Parmi les auteurs des attentats en France, 60% étaient de nationalité étrangère. » « 25 % étaient des réfugiés politiques en France, tandis que 25 % étaient en situation irrégulière. »",
  "Centre d'analyse privé spécialisé ; petit échantillon et quelques incohérences internes de pourcentages dans le rapport.", 'etude'))
PE_AN_QE10244_2024 = ('pe_an_qe10244_2024', src("Question écrite n° 10244 « Menaces de l'extrême-droite contre la République », et réponse du ministère de l'Intérieur", 'Assemblée nationale (réponse du ministère de l\'Intérieur et des Outre-mer)', 'réponse publiée au JO le 9 avril 2024',
  'https://www.assemblee-nationale.fr/dyn/16/questions/QANR5L16QE10244.pdf',
  "Dans sa réponse sur la menace de l'ultra-droite, le ministère indique : « Une vigilance étroite s'exerce à l'endroit de la mouvance d'ultra-droite en France. » Les services inscrivent des personnes au fichier des interdits d'armes et les en dessaisissent. « Au global, l'action menée par le ministère de l'Intérieur et des Outre-mer a ainsi permis de déjouer 12 projets d'action terroriste depuis 2017, dont 2 en 2023. »",
  "Réponse ministérielle officielle.", 'primaire'))
PE_EUROPOL_TESAT_2024 = ('pe_europol_tesat_2024', src('EU Terrorism Situation and Trend Report (TE-SAT) 2024 – Executive Summary', 'Europol', '2024',
  'https://www.europol.europa.eu/cms/sites/default/files/documents/TE-SAT%202024%20-%20Executive%20Summary%20-%20EN.pdf',
  "« A total of 120 terrorist attacks (98 completed, 9 failed and 13 foiled) were carried out in 7 EU Member States in 2023. » 426 personnes arrêtées dans 22 États membres. Des jeunes adultes et des mineurs ont participé à la préparation d'attentats ; les réseaux sociaux et messageries chiffrées servent à diffuser la propagande ; pour le terrorisme d'extrême droite, les acteurs isolés ou petits groupes « pose the highest threat ».",
  "Agence européenne de police ; le résumé ne donne pas de données de nationalité.", 'primaire'))

FICHES.append(fiche(
 id='terroristes-immigres-refugies', affirmation="Les terroristes sont presque tous des immigrés ou des réfugiés.", volet='immigration', sous_theme='Immigration et délinquance',
 mots_cles=['terroristes immigres', 'terroristes refugies', 'attentats etrangers', 'terroristes tous etrangers', 'djihadistes francais', 'terrorisme immigration', 'attentats migrants', 'terroristes nes en france', 'refugies terroristes', 'islamistes etrangers'],
 verdict='trompeur', fiabilite='estimation',
 resume="Trompeur. Sur la longue période, la grande majorité des djihadistes condamnés en France sont des Français, nés et élevés en France : sur 130 condamnés étudiés par l'Ifri (jugements 2004-2017), seuls 11 étaient étrangers. Mais le profil a changé récemment : selon le Centre d'analyse du terrorisme, 60 % des auteurs d'attentats commis en France entre 2020 et 2023 étaient étrangers, dont une partie de réfugiés ou de personnes en situation irrégulière. « Presque tous » reste faux, et le terrorisme d'ultra-droite, lui, est surtout le fait de Français.",
 contexte="Après chaque attentat, la nationalité de l'auteur devient le cœur du débat. Plusieurs attaques récentes, commises par des étrangers, ont renforcé l'idée que le terrorisme serait importé.",
 explication="Il faut distinguer les périodes, les attentats commis et les projets déjoués, et regarder des études qui comptent tous les cas, pas seulement ceux qui ont marqué l'actualité.",
 sources=[PE_IFRI_HECKER_2018, PE_CAT_2024, PE_AN_QE10244_2024, PE_EUROPOL_TESAT_2024],
 faits=[
  fait("Sur 130 personnes condamnées pour terrorisme djihadiste en France dont la nationalité est connue (jugements de 2004 à 2017), l'Ifri compte 90 Français, 29 binationaux et 11 étrangers.", 'pe_ifri_hecker_2018', '2004-2017', 'France', "Le djihadisme de la décennie des grands attentats a surtout été le fait de Français.", 'etabli', '11 étrangers sur 130'),
  fait("Selon l'Ifri, ces condamnés sont « en grande majorité nés en France et ont grandi dans ce pays » ; 26 % sont des convertis et 40 % viennent d'un quartier prioritaire.", 'pe_ifri_hecker_2018', '2004-2017', 'France', "La radicalisation s'est faite ici, souvent dans des quartiers relégués, pas à l'étranger.", 'etabli', '26 %'),
  fait("Sur les 39 personnes impliquées dans des attentats, tentatives ou projets islamistes en France entre 2020 et 2023, 13 des 29 dont la nationalité est connue sont Françaises (44,8 %).", 'pe_cat_2024', '2020-2023', 'France', "Même sur la période récente, près de la moitié des personnes impliquées sont françaises.", 'estimation', '44,8 %'),
  fait("Fait défavorable : selon le Centre d'analyse du terrorisme, 60 % des auteurs d'attentats commis en France entre 2020 et 2023 étaient de nationalité étrangère ; 25 % étaient réfugiés et 25 % en situation irrégulière.", 'pe_cat_2024', '2020-2023', 'France', "Le profil des auteurs récents a changé ; il faut le reconnaître, même si l'échantillon est petit (8 attentats aboutis).", 'estimation', '60 %'),
  fait("Le ministère de l'Intérieur indique avoir déjoué 12 projets d'action terroriste depuis 2017, dont 2 en 2023, dans sa réponse sur la menace de l'ultra-droite.", 'pe_an_qe10244_2024', '2017-2023', 'France', "Le terrorisme ne vient pas d'un seul camp : l'ultra-droite prépare aussi des attentats.", 'etabli', '12 projets'),
  fait("Europol relève qu'en 2023 des jeunes adultes et des mineurs ont participé à des projets d'attentats dans l'Union, souvent radicalisés en ligne.", 'pe_europol_tesat_2024', '2023', 'Union européenne', "La radicalisation passe de plus en plus par Internet, quel que soit le pays de naissance.", 'etabli'),
 ],
 court="Faux dans sa généralité : sur 130 djihadistes condamnés en France étudiés par l'Ifri, seuls 11 étaient étrangers, la plupart étant nés et élevés en France. Depuis 2020, la part d'étrangers parmi les auteurs d'attentats a augmenté, mais elle reste loin de « presque tous ».",
 moyen="L'étude de l'Ifri sur 137 djihadistes condamnés en France (jugements de 2004 à 2017) est claire : 90 Français, 29 binationaux, 11 étrangers sur 130 cas connus, en grande majorité nés et élevés en France. Un quart sont des convertis.\n\nLa période récente est différente : selon le Centre d'analyse du terrorisme, 60 % des auteurs d'attentats commis entre 2020 et 2023 étaient étrangers, dont certains réfugiés ou sans papiers. Mais sur l'ensemble des personnes impliquées, près de la moitié sont françaises. Et l'ultra-droite, française, a vu 12 projets d'attentats déjoués depuis 2017.",
 detaille="Pour la décennie des grands attentats, les chiffres sont nets. Marc Hecker, de l'Ifri, a étudié 137 personnes condamnées pour terrorisme djihadiste en France. Sur 130 dont la nationalité est connue, 90 sont françaises, 29 binationales et 11 étrangères. La grande majorité est née et a grandi en France ; 26 % sont des convertis, 40 % viennent de quartiers prioritaires. Le djihadisme de cette époque est d'abord un phénomène « fait maison ».\n\nIl faut être honnête sur la période récente. Le Centre d'analyse du terrorisme a étudié les attentats, tentatives et projets de 2020 à 2023. Parmi les auteurs d'attentats, 60 % étaient étrangers ; un quart étaient réfugiés, un quart en situation irrégulière. Mais il s'agit d'un petit nombre de cas (8 attentats aboutis), et sur les 39 personnes impliquées, près de la moitié de celles dont la nationalité est connue sont françaises.\n\nEnfin, le terrorisme ne se limite pas au djihadisme. Le ministère de l'Intérieur indique avoir déjoué 12 projets d'action terroriste depuis 2017 dans sa réponse sur l'ultra-droite, et Europol souligne la radicalisation en ligne de jeunes de toutes origines. Lutter contre le terrorisme demande du renseignement, de la prévention et un suivi des personnes radicalisées, pas des soupçons sur tous les immigrés.",
 empathie="Après un attentat, la peur et la colère sont légitimes. Chercher à comprendre qui frappe et pourquoi, c'est normal ; encore faut-il regarder tous les cas, pas seulement ceux qu'on retient.",
 legitimes=["Plusieurs attentats récents ont été commis par des étrangers, parfois réfugiés ou en situation irrégulière.", "Le suivi des étrangers radicalisés et l'exécution des expulsions posent de vraies questions de politique publique."],
 contre=[
  ("Les derniers attentats ont tous été commis par des étrangers.", "Sur 2020-2023, c'est 60 % des auteurs d'attentats selon le CAT, sur un petit nombre de cas ; près de la moitié des personnes impliquées dans l'ensemble des projets sont françaises."),
  ("S'il n'y avait pas d'immigration, il n'y aurait pas de terrorisme.", "Sur 130 djihadistes condamnés étudiés par l'Ifri, 119 étaient français ou binationaux, en majorité nés en France ; et l'ultra-droite prépare aussi des attentats."),
 ],
 questions=["Savais-tu que la grande majorité des djihadistes condamnés en France entre 2004 et 2017 étaient nés en France ?", "Si la radicalisation se fait surtout ici et sur Internet, quelles mesures seraient vraiment efficaces ?"],
 limites=["L'étude de l'Ifri porte sur des jugements de 2004 à 2017 : elle est ancienne et ne couvre pas les attentats récents.", "Le rapport du CAT repose sur un petit nombre de cas (8 attentats aboutis) et contient quelques incohérences de pourcentages ; le nombre exact d'auteurs derrière les 60 % n'est pas donné.", "« Immigré » (né étranger à l'étranger) et « étranger » ne se recoupent pas : aucune source lue ne donne la part d'immigrés naturalisés parmi les auteurs.", "Le résumé d'Europol ne donne pas de données de nationalité."],
 publics={'convaincus': "Regarde les condamnations : sur 130 djihadistes jugés en France étudiés par l'Ifri, 11 seulement étaient étrangers, la plupart étaient nés ici. C'est vrai que les auteurs récents sont plus souvent étrangers, mais « presque tous », c'est faux. Et l'ultra-droite, française, prépare aussi des attentats.",
  'indecis': "Avoir peur après un attentat, c'est humain, et il est vrai que plusieurs auteurs récents étaient étrangers. Mais sur la durée, la plupart des djihadistes condamnés en France sont des Français radicalisés ici. Le vrai enjeu, c'est le renseignement, la prévention et le suivi des personnes radicalisées."},
 a_actualiser='2027-06-30', raison="Nouveau rapport Europol TE-SAT et éventuelles études actualisées sur le profil des auteurs d'attentats.",
))

# 2 ── UNRWA, aide humanitaire et Hamas ──────────────────────────────────────
PE_ONU_OIOS_2024 = ('pe_onu_oios_2024', src('Nine UNRWA staff to be fired for potential role in 7 October attacks on Israel', 'ONU Info (UN News)', '5 août 2024',
  'https://news.un.org/en/story/2024/08/1152841',
  "Le Bureau des services de contrôle interne (OIOS) a examiné les accusations visant 19 employés. « In one case, no evidence was obtained by OIOS to support the allegations » ; dans neuf autres cas, les preuves étaient insuffisantes ; pour les neuf derniers, les éléments indiquaient qu'ils pourraient avoir été impliqués dans les attaques du 7 octobre, et l'UNRWA met fin à leurs contrats. « OIOS was not able to independently authenticate most of the information provided to it », les informations restant aux mains des autorités israéliennes.",
  "Service d'information officiel des Nations unies.", 'primaire'))
PE_EURONEWS_COLONNA_2024 = ('pe_euronews_colonna_2024', src('UNRWA report says Israel has provided no evidence of terror links', 'Euronews', '23 avril 2024',
  'https://www.euronews.com/2024/04/23/unrwa-report-says-israel-has-provided-no-evidence-of-terror-links',
  "La revue indépendante dirigée par Catherine Colonna conclut qu'Israël n'a pas fourni de preuves de ses accusations selon lesquelles des centaines d'employés de l'UNRWA appartiendraient à des groupes terroristes ; Israël n'avait émis aucune inquiétude sur les listes de personnel depuis 2011. L'UNRWA dispose de procédures « robustes » de neutralité, avec de sérieuses lacunes d'application. L'agence compte environ 32 000 employés, dont 13 000 à Gaza. Environ 15 pays avaient suspendu leur financement ; la plupart l'ont repris.",
  "Grand média européen rendant compte du rapport Colonna ; le rapport lui-même n'a pas été ouvert.", 'secondaire'))
PE_NPR_COLONNA_2024 = ('pe_npr_colonna_2024', src('Report on UNRWA concludes Israel has not provided evidence of employees\' militancy', 'NPR', '23 avril 2024',
  'https://www.npr.org/2024/04/23/1246613547/unrwa-israel-hamas-gaza-war',
  "Le rapport Colonna : « However, Israel has yet to provide supporting evidence of this. » Il relève des problèmes de neutralité : enquêtes insuffisantes sur les manquements, employés exprimant des opinions politiques, locaux utilisés à des fins « political or military », contenus problématiques dans des manuels scolaires. La revue n'a pas examiné l'accusation visant une douzaine d'employés, confiée à l'OIOS. Elle recommande un meilleur contrôle du personnel et une revue des manuels.",
  "Radio publique américaine ; compte rendu du rapport.", 'secondaire'))
PE_NPR_TUNNELS_2024 = ('pe_npr_tunnels_2024', src("Israel says it discovered tunnels under U.N. agency's Gaza headquarters", 'NPR (republié par NHPR)', '10 février 2024',
  'https://www.nhpr.org/2024-02-10/israel-says-it-discovered-tunnels-under-u-n-agencys-gaza-headquarters',
  "L'armée israélienne affirme avoir trouvé un réseau de tunnels sous le siège de l'UNRWA à Gaza, alimenté en électricité depuis le bâtiment, et des armes dans des pièces du bâtiment ; la visite était encadrée par l'armée. Le chef de l'UNRWA, Philippe Lazzarini, dit que l'agence ignorait ce qui se trouvait sous son siège, évacué le 12 octobre, et que ces accusations « merit an independent inquiry that is currently not possible ».",
  "Radio publique américaine ; affirmations de l'armée israélienne non vérifiées de façon indépendante.", 'secondaire'))
PE_CE_REVUE_2023 = ('pe_ce_revue_2023', src('Commission finalises review of EU aid to Palestine', 'Commission européenne', '21 novembre 2023',
  'https://enlargement.ec.europa.eu/news/commission-finalises-review-eu-aid-palestine-2023-11-21_en',
  "La revue de l'ensemble du portefeuille d'aide au développement (hors aide humanitaire) conclut que « no evidence has been found to date that money has been diverted for unintended purposes ». Ursula von der Leyen : « This review has confirmed that the safeguards in place are effective. » La Commission ajoute des clauses contre l'incitation à la haine dans tous les nouveaux contrats et demande des informations complémentaires aux bénéficiaires.",
  "Communiqué officiel de la Commission européenne.", 'primaire'))
PE_EURONEWS_REPRISE_2024 = ('pe_euronews_reprise_2024', src('EU to continue funding UNRWA as it probes alleged staff involvement in Oct 7 attacks', 'Euronews', '1er mars 2024',
  'https://www.euronews.com/2024/03/01/eu-to-continue-funding-unrwa-as-it-probes-alleged-staff-involvement-in-oct-7-attacks',
  "La Commission débloque 82 millions d'euros pour l'UNRWA en 2024, dont une première tranche de 50 millions, après que l'agence a accepté un audit de ses recrutements, un renforcement du contrôle interne et la vérification de son personnel. Les responsables européens indiquent qu'Israël n'a pas encore fourni de preuves de ses accusations contre 12 employés.",
  "Grand média européen.", 'secondaire'))
PE_RTE_USAID_2025 = ('pe_rte_usaid_2025', src('USAID analysis found no evidence of Hamas theft of Gaza aid (avec Reuters)', 'RTÉ (avec Reuters)', '25 juillet 2025',
  'https://www.rte.ie/news/middle-east/2025/0725/1525272-usaid-gaza-aid',
  "Une analyse interne du Bureau de l'aide humanitaire de l'USAID a examiné 156 incidents de vol ou de perte de fournitures financées par les États-Unis à Gaza, d'octobre 2023 à mai 2025. Elle n'a trouvé « no reports alleging Hamas » bénéficiant de ces fournitures ; au moins 44 incidents étaient liés directement ou indirectement à des actions militaires israéliennes. L'étude reconnaît que des fournitures ont pu atteindre des fonctionnaires de l'administration du Hamas ; l'absence de signalement « does not mean that diversion has not occurred ». Le Département d'État conteste ces conclusions.",
  "Radiotélévision publique irlandaise reprenant une exclusivité Reuters ; document interne non publié.", 'secondaire'))

PE_PUBLICSENAT_UNRWA_2024 = ('pe_publicsenat_unrwa_2024', src("Décryptage : ce qu'Israël reproche à l'UNRWA, l'agence de l'ONU pour les réfugiés palestiniens", 'Public Sénat', '30 octobre 2024',
  'https://www.publicsenat.fr/actualites/international/decryptage-ce-quisrael-reproche-a-lunrwa-lagence-de-lonu-pour-les-refugies-palestiniens',
  "Le Parlement israélien a adopté par 92 voix contre 10 deux textes interdisant toute activité de l'UNRWA « sur le territoire israélien ». Israël accuse l'agence de contribuer à l'emprise du Hamas sur Gaza. Le rapport Colonna recommande de renforcer les mécanismes de neutralité ; selon le chercheur Jean-Paul Chagnollaud, « Les experts ont conclu qu'il n'y avait aucune preuve de complicité entre l'Unrwa et le Hamas ». L'agence compte 30 000 employés, dont 13 000 à Gaza.",
  "Chaîne parlementaire ; analyse s'appuyant sur des chercheurs.", 'secondaire'))

FICHES.append(fiche(
 id='unrwa-gaza-hamas', affirmation="L'aide humanitaire à Gaza et l'UNRWA financent le Hamas.", volet='international', sous_theme='Palestine et Israël',
 mots_cles=['unrwa hamas', 'aide humanitaire gaza hamas', 'unrwa terroristes', 'aide gaza detournee', 'rapport colonna', 'unrwa 7 octobre', 'financement unrwa', 'hamas vole l aide', 'aide europeenne palestine', 'unrwa employes hamas'],
 verdict='trompeur', fiabilite='estimation',
 resume="Trompeur. Des employés de l'UNRWA ont pu participer au 7 octobre : l'enquête interne de l'ONU a conclu que 9 d'entre eux pourraient avoir été impliqués et ils ont été licenciés. Mais aucune enquête n'a montré que l'agence ou l'aide finançaient le Hamas. Le rapport Colonna note qu'Israël n'a pas fourni de preuves de liens massifs ; la Commission européenne n'a trouvé aucun détournement de son aide ; une analyse de l'USAID sur 156 incidents n'a trouvé aucun signalement de vol au profit du Hamas.",
 contexte="En janvier 2024, Israël a accusé une douzaine d'employés de l'UNRWA d'avoir participé aux attaques du 7 octobre 2023. Une quinzaine de pays ont suspendu leurs financements, puis la plupart les ont repris. En octobre 2024, le Parlement israélien a interdit les activités de l'agence sur son territoire.",
 explication="Il faut séparer trois questions : des employés ont-ils participé au 7 octobre ? L'agence est-elle infiltrée de façon massive ? L'argent de l'aide est-il détourné vers le Hamas ? Les enquêtes ne répondent pas de la même façon à chacune.",
 sources=[PE_ONU_OIOS_2024, PE_EURONEWS_COLONNA_2024, PE_NPR_COLONNA_2024, PE_NPR_TUNNELS_2024, PE_CE_REVUE_2023, PE_EURONEWS_REPRISE_2024, PE_RTE_USAID_2025, PE_PUBLICSENAT_UNRWA_2024],
 faits=[
  fait("Fait défavorable : sur 19 employés de l'UNRWA mis en cause, l'enquête interne de l'ONU (OIOS) a conclu que 9 pourraient avoir été impliqués dans les attaques du 7 octobre ; ils ont été licenciés. Pour 9 autres, les preuves étaient insuffisantes, et pour 1, aucune preuve n'a été trouvée.", 'pe_onu_oios_2024', '2024', 'Gaza', "Des employés ont pu participer à un massacre ; c'est grave, et l'ONU l'a reconnu.", 'etabli', '9 sur 19'),
  fait("Selon le rapport Colonna, Israël n'a pas fourni de preuves de ses accusations selon lesquelles des centaines d'employés appartiendraient à des groupes terroristes ; l'UNRWA compte environ 32 000 employés, dont 13 000 à Gaza.", 'pe_euronews_colonna_2024', '2024', 'Gaza et région', "Neuf employés possiblement impliqués sur 13 000 à Gaza, ce n'est pas une agence au service du Hamas.", 'etabli', '13 000'),
  fait("Le rapport Colonna relève aussi des problèmes de neutralité : employés exprimant des opinions politiques, locaux utilisés à des fins politiques ou militaires, contenus problématiques dans certains manuels.", 'pe_npr_colonna_2024', '2024', 'Zones d\'action de l\'UNRWA', "Les failles existent et doivent être corrigées ; elles ne prouvent pas un financement du Hamas.", 'etabli'),
  fait("Fait défavorable : l'armée israélienne affirme avoir découvert en 2024 des tunnels du Hamas sous le siège de l'UNRWA à Gaza ; l'agence dit l'avoir ignoré et demande une enquête indépendante.", 'pe_npr_tunnels_2024', '2024', 'Gaza', "Le Hamas a pu exploiter des infrastructures civiles ; cela n'a pas été vérifié de façon indépendante.", 'interpretation'),
  fait("En novembre 2023, la Commission européenne a examiné tout son portefeuille d'aide au développement en Palestine et n'a trouvé aucune preuve de détournement ; en mars 2024, elle a débloqué 82 millions d'euros pour l'UNRWA en échange d'audits et de contrôles renforcés.", 'pe_ce_revue_2023', '2023-2024', 'Union européenne', "Le premier donateur a contrôlé son aide et n'a pas trouvé de financement du Hamas.", 'etabli', '82 millions d’euros'),
  fait("Une analyse interne de l'USAID sur 156 incidents de vol ou de perte d'aide américaine à Gaza (octobre 2023 à mai 2025) n'a trouvé aucun signalement de détournement au profit du Hamas ; elle admet que de l'aide a pu atteindre des fonctionnaires du Hamas.", 'pe_rte_usaid_2025', '2023-2025', 'Gaza', "Même un gouvernement américain hostile à l'UNRWA n'a pas trouvé de vol massif par le Hamas.", 'estimation', '156 incidents'),
 ],
 court="Trompeur : 9 employés de l'UNRWA, sur 13 000 à Gaza, pourraient avoir participé au 7 octobre selon l'ONU, et ils ont été licenciés. Mais ni le rapport Colonna, ni la Commission européenne, ni une analyse de l'USAID n'ont trouvé de financement du Hamas par l'aide.",
 moyen="Il y a un fait grave : l'enquête interne de l'ONU a conclu que 9 employés de l'UNRWA pourraient avoir participé aux attaques du 7 octobre ; ils ont été licenciés. Le rapport Colonna a aussi relevé des failles de neutralité.\n\nMais cela ne veut pas dire que l'aide finance le Hamas. Le même rapport note qu'Israël n'a pas prouvé ses accusations de liens massifs. La Commission européenne a contrôlé son aide et n'a trouvé aucun détournement. Une analyse de l'USAID sur 156 incidents de pertes d'aide n'a trouvé aucun signalement au profit du Hamas.",
 detaille="L'UNRWA emploie environ 32 000 personnes, dont 13 000 à Gaza, pour l'école, la santé et l'aide alimentaire des réfugiés palestiniens. En janvier 2024, Israël a accusé une douzaine d'employés d'avoir participé aux attaques du 7 octobre. L'enquête interne de l'ONU a examiné 19 cas : 9 employés pourraient avoir été impliqués et ont été licenciés, les preuves étaient insuffisantes pour 9 autres, et aucune preuve n'a été trouvée pour le dernier. L'ONU précise qu'elle n'a pas pu authentifier la plupart des informations, restées aux mains d'Israël.\n\nLe rapport Colonna, commandé par le secrétaire général de l'ONU, juge les règles de neutralité de l'agence solides, mais mal appliquées : opinions politiques d'employés, locaux utilisés à des fins politiques ou militaires, manuels problématiques. Il souligne aussi qu'Israël n'a pas fourni de preuves que des centaines d'employés appartiendraient à des groupes armés. L'armée israélienne affirme avoir trouvé des tunnels sous le siège de l'agence, ce que l'UNRWA dit avoir ignoré ; aucune enquête indépendante n'a pu le vérifier.\n\nSur l'argent, les contrôles n'ont pas trouvé de financement du Hamas. La Commission européenne a passé en revue son aide au développement en 2023 sans trouver de détournement, puis a repris son financement de l'UNRWA en 2024 contre des audits renforcés. Une analyse de l'USAID sur 156 incidents de pertes d'aide n'a trouvé aucun signalement au profit du Hamas, même si elle reconnaît des angles morts. Couper l'aide punit surtout une population civile affamée ; renforcer les contrôles, c'est ce qu'ont choisi la plupart des donateurs.",
 empathie="Apprendre que des employés d'une agence de l'ONU ont pu participer à un massacre choque, et c'est normal de se demander où va l'argent. Cette question mérite des réponses précises.",
 legitimes=["L'ONU a conclu que 9 employés de l'UNRWA pourraient avoir participé au 7 octobre.", "Le rapport Colonna a relevé de vraies failles de neutralité dans l'agence.", "Dans une zone contrôlée par le Hamas, aucun contrôle de l'aide ne peut être parfait."],
 contre=[
  ("Si 9 employés ont participé au 7 octobre, toute l'agence est complice.", "Ce sont 9 personnes sur environ 13 000 employés à Gaza ; elles ont été licenciées, et Israël n'a pas prouvé l'existence de liens massifs selon le rapport Colonna."),
  ("Le Hamas vole l'aide humanitaire.", "Une analyse de l'USAID sur 156 incidents de pertes n'a trouvé aucun signalement de vol au profit du Hamas, et la Commission européenne n'a trouvé aucun détournement de son aide."),
  ("Il faut couper l'aide pour affaiblir le Hamas.", "La plupart des pays qui avaient suspendu leurs fonds les ont rétablis, avec des contrôles renforcés, parce que l'aide nourrit et soigne des civils."),
 ],
 questions=["Savais-tu que la Commission européenne a contrôlé toute son aide au développement en Palestine sans trouver de détournement ?", "Si l'on coupe l'aide, qui en souffre le plus : le Hamas ou les enfants de Gaza ?"],
 limites=["Le rapport Colonna et le rapport de l'OIOS n'ont pas été ouverts directement ; ils sont connus par l'ONU et la presse.", "L'analyse de l'USAID est un document interne non publié, connu par Reuters ; le Département d'État la conteste.", "Les affirmations sur les tunnels viennent de l'armée israélienne et n'ont pas été vérifiées de façon indépendante.", "La revue européenne de 2023 portait sur l'aide au développement, pas sur l'aide humanitaire."],
 publics={'convaincus': "Oui, l'ONU a reconnu que 9 employés de l'UNRWA ont pu participer au 7 octobre, et ils ont été renvoyés. Mais c'est 9 sur 13 000 à Gaza. Quand l'Union européenne et même l'administration américaine ont cherché l'argent détourné vers le Hamas, elles n'ont rien trouvé de tel.",
  'indecis': "C'est normal de vouloir que l'aide n'aille pas aux terroristes. Les enquêtes ont trouvé des employés fautifs et des failles de neutralité, mais pas de financement du Hamas par l'aide. Renforcer les contrôles, c'est la voie choisie par la plupart des pays, pour ne pas affamer des civils."},
 a_actualiser='2027-03-31', raison="Évolution du statut de l'UNRWA, nouvelles enquêtes de l'ONU et décisions des donateurs.",
))

